package com.runeprofile.modelexporter;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.NonNull;

import javax.annotation.Nullable;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * Serialises a {@link MeshData} to a binary glTF (.glb) file.
 * <p>
 * The output is one mesh whose primitives all share a single vertex buffer,
 * one per group of faces that can be drawn with the same material. Materials
 * are unlit, because the game does no lighting: the colour you see is the
 * vertex colour multiplied by the texel, which is exactly what glTF's base
 * colour factor, base colour texture and COLOR_0 attribute multiply out to.
 * <p>
 * Textures are either embedded in the file, which makes a single self contained
 * model that any glTF viewer will open, or referenced by URL so they can be
 * served once from a CDN and shared across every profile.
 */
public final class GlbWriter {
    private static final int GLB_MAGIC = 0x46546C67; // "glTF"
    private static final int GLB_VERSION = 2;
    private static final int CHUNK_JSON = 0x4E4F534A;
    private static final int CHUNK_BIN = 0x004E4942;

    private static final int TARGET_ARRAY_BUFFER = 34962;
    private static final int TARGET_ELEMENT_ARRAY_BUFFER = 34963;

    private static final int COMPONENT_UNSIGNED_BYTE = 5121;
    private static final int COMPONENT_UNSIGNED_SHORT = 5123;
    private static final int COMPONENT_UNSIGNED_INT = 5125;
    private static final int COMPONENT_FLOAT = 5126;

    private static final int FILTER_NEAREST = 9728;
    private static final int FILTER_LINEAR_MIPMAP_LINEAR = 9987;
    private static final int WRAP_REPEAT = 10497;

    /**
     * Game models are around 128 units per tile. Scaling the root node rather
     * than the vertex data keeps positions as exact small integers and still
     * gives a roughly human sized character in any viewer that assumes metres.
     */
    private static final float UNITS_PER_METRE = 128f;

    /** UNSIGNED_SHORT indices stop here; 65535 is reserved as a restart value. */
    private static final int MAX_SHORT_INDEX = 65535;

    /** How the file should refer to its textures. */
    public static final class Options {
        private boolean embedTextures = true;
        private String textureUrlTemplate;
        private String modelName = "model";
        private Map<String, Object> extras;

        /** Embed texture PNGs in the file. Self contained but not shared between models. */
        public Options embedTextures() {
            this.embedTextures = true;
            this.textureUrlTemplate = null;
            return this;
        }

        /**
         * Reference textures by URL instead of embedding them. The template
         * takes the texture id, e.g. {@code https://cdn.example.com/texture/%d.png}.
         */
        public Options textureUrls(@NonNull String template) {
            this.embedTextures = false;
            this.textureUrlTemplate = template;
            return this;
        }

        public Options modelName(@NonNull String modelName) {
            this.modelName = modelName;
            return this;
        }

        /** Arbitrary metadata to attach to the glTF asset. */
        public Options extras(@Nullable Map<String, Object> extras) {
            this.extras = extras;
            return this;
        }
    }

    private GlbWriter() {
    }

    public static byte[] write(@NonNull Gson gson, @NonNull MeshData mesh,
                               @NonNull TextureLookup textures,
                               @NonNull Options options) throws IOException {
        if (mesh.isEmpty()) {
            throw new IOException("Refusing to write an empty model");
        }

        final BinaryChunk bin = new BinaryChunk();

        final JsonArray bufferViews = new JsonArray();
        final JsonArray accessors = new JsonArray();
        final JsonArray materials = new JsonArray();
        final JsonArray gltfTextures = new JsonArray();
        final JsonArray images = new JsonArray();
        // Several primitives can share a texture: the same cape is split by
        // translucency. Each needs its own material but they must all point at
        // one image, or the PNG is embedded once per group.
        final Map<Integer, Integer> textureIndexById = new HashMap<>();

        // Vertex attributes, shared by every primitive.
        final int positionAccessor = addAccessor(bufferViews, accessors, bin,
                floatsToBytes(mesh.getPositions()), TARGET_ARRAY_BUFFER,
                COMPONENT_FLOAT, "VEC3", mesh.getVertexCount(), mesh.getMin(), mesh.getMax(), false);

        final int colorAccessor = addAccessor(bufferViews, accessors, bin,
                mesh.getColors(), TARGET_ARRAY_BUFFER,
                COMPONENT_UNSIGNED_BYTE, "VEC4", mesh.getVertexCount(), null, null, true);

        final int uvAccessor = mesh.getUvs() == null ? -1 : addAccessor(bufferViews, accessors, bin,
                floatsToBytes(mesh.getUvs()), TARGET_ARRAY_BUFFER,
                COMPONENT_FLOAT, "VEC2", mesh.getVertexCount(), null, null, false);

        // Face render priority travels per vertex under a custom attribute name,
        // so a renderer can offset by it without the exporter having to split
        // primitives - which translucency cannot afford, since all of it has to
        // share one mesh to be sorted.
        final int priorityAccessor = mesh.getPriorities() == null ? -1
                : addAccessor(bufferViews, accessors, bin,
                        floatsToBytes(mesh.getPriorities()), TARGET_ARRAY_BUFFER,
                        COMPONENT_FLOAT, "SCALAR", mesh.getVertexCount(), null, null, false);

        // One index buffer view for the whole mesh; each primitive gets an
        // accessor pointing at its own slice of it.
        final boolean wideIndices = mesh.getVertexCount() > MAX_SHORT_INDEX;
        final int indexComponentType = wideIndices ? COMPONENT_UNSIGNED_INT : COMPONENT_UNSIGNED_SHORT;
        final int indexStride = wideIndices ? 4 : 2;
        final int indexBufferView = addBufferView(bufferViews, bin,
                indicesToBytes(mesh.getIndices(), wideIndices), TARGET_ELEMENT_ARRAY_BUFFER, 0);

        final JsonArray primitives = new JsonArray();

        for (MeshData.Primitive primitive : mesh.getPrimitives()) {
            final GameTextures.TextureData texture = primitive.isTextured()
                    ? textures.get(primitive.getTextureId())
                    : null;

            final JsonObject accessor = new JsonObject();
            accessor.addProperty("bufferView", indexBufferView);
            accessor.addProperty("byteOffset", primitive.getIndexOffset() * indexStride);
            accessor.addProperty("componentType", indexComponentType);
            accessor.addProperty("count", primitive.getIndexCount());
            accessor.addProperty("type", "SCALAR");
            accessors.add(accessor);
            final int indexAccessor = accessors.size() - 1;

            // A texture whose pixels could not be read still contributes its
            // average colour to the material, so the surface degrades to a flat
            // approximation instead of the bare grey the lightness alone gives.
            final boolean hasImage = texture != null
                    && (options.embedTextures ? texture.getPng() != null : true);

            final JsonObject attributes = new JsonObject();
            attributes.addProperty("POSITION", positionAccessor);
            attributes.addProperty("COLOR_0", colorAccessor);
            // Only textured primitives declare UVs, even though the accessor is
            // shared, so an untextured primitive costs nothing extra.
            if (hasImage && uvAccessor != -1) {
                attributes.addProperty("TEXCOORD_0", uvAccessor);
            }
            if (priorityAccessor != -1) {
                attributes.addProperty("_PRIORITY", priorityAccessor);
            }

            final JsonObject gltfPrimitive = new JsonObject();
            gltfPrimitive.add("attributes", attributes);
            gltfPrimitive.addProperty("indices", indexAccessor);
            gltfPrimitive.addProperty("material", materials.size());
            primitives.add(gltfPrimitive);

            int textureIndex = -1;
            if (hasImage) {
                Integer existing = textureIndexById.get(texture.getId());
                if (existing == null) {
                    gltfTextures.add(buildTexture(images.size()));
                    images.add(buildImage(texture, options, bufferViews, bin));
                    existing = gltfTextures.size() - 1;
                    textureIndexById.put(texture.getId(), existing);
                }
                textureIndex = existing;
            }

            materials.add(buildMaterial(primitive, texture, hasImage, textureIndex));
        }

        final JsonObject mesh0 = new JsonObject();
        mesh0.add("primitives", primitives);
        mesh0.addProperty("name", options.modelName);

        final float scale = 1f / UNITS_PER_METRE;
        final JsonObject node0 = new JsonObject();
        node0.addProperty("mesh", 0);
        node0.addProperty("name", options.modelName);
        node0.add("scale", jsonArray(scale, scale, scale));

        final JsonObject asset = new JsonObject();
        asset.addProperty("version", "2.0");
        asset.addProperty("generator", "RuneProfile");
        if (options.extras != null && !options.extras.isEmpty()) {
            asset.add("extras", gson.toJsonTree(options.extras));
        }

        final JsonObject gltf = new JsonObject();
        gltf.add("asset", asset);
        gltf.addProperty("scene", 0);
        gltf.add("scenes", singletonArray(sceneWithNode()));
        gltf.add("nodes", singletonArray(node0));
        gltf.add("meshes", singletonArray(mesh0));
        gltf.add("materials", materials);
        if (gltfTextures.size() > 0) {
            gltf.add("textures", gltfTextures);
            gltf.add("images", images);
            gltf.add("samplers", singletonArray(buildSampler()));
        }
        gltf.add("accessors", accessors);
        gltf.add("bufferViews", bufferViews);

        final JsonObject buffer = new JsonObject();
        buffer.addProperty("byteLength", bin.size());
        gltf.add("buffers", singletonArray(buffer));

        final JsonArray extensionsUsed = new JsonArray();
        extensionsUsed.add("KHR_materials_unlit");
        gltf.add("extensionsUsed", extensionsUsed);

        return assemble(gson.toJson(gltf), bin.toByteArray());
    }

    /** Resolves a texture id to its pixels; lets the writer stay free of client types. */
    public interface TextureLookup {
        @Nullable
        GameTextures.TextureData get(int textureId);
    }

    private static JsonObject sceneWithNode() {
        final JsonArray nodes = new JsonArray();
        nodes.add(0);
        final JsonObject scene = new JsonObject();
        scene.add("nodes", nodes);
        return scene;
    }

    private static JsonObject buildMaterial(MeshData.Primitive primitive,
                                            @Nullable GameTextures.TextureData texture,
                                            boolean hasImage,
                                            int textureIndex) {
        final JsonObject pbr = new JsonObject();
        if (hasImage) {
            pbr.add("baseColorFactor", jsonArray(1f, 1f, 1f, 1f));
            final JsonObject baseColorTexture = new JsonObject();
            baseColorTexture.addProperty("index", textureIndex);
            pbr.add("baseColorTexture", baseColorTexture);
        } else if (texture != null) {
            final int average = texture.getAverageColor();
            pbr.add("baseColorFactor", jsonArray(
                    ((average >> 16) & 0xff) / 255f,
                    ((average >> 8) & 0xff) / 255f,
                    (average & 0xff) / 255f,
                    1f));
        } else {
            pbr.add("baseColorFactor", jsonArray(1f, 1f, 1f, 1f));
        }
        pbr.addProperty("metallicFactor", 0f);
        pbr.addProperty("roughnessFactor", 1f);

        final JsonObject material = new JsonObject();
        material.addProperty("name", texture == null
                ? "untextured"
                : "texture-" + texture.getId());
        material.add("pbrMetallicRoughness", pbr);
        // The game does not light models, so an unlit material is not a
        // simplification here, it is the accurate one.
        material.add("extensions", unlitExtension());
        // Game models are routinely viewed from both sides and their winding is
        // not reliably outward, so culling would punch holes in them.
        material.addProperty("doubleSided", true);

        if (primitive.isTranslucent()) {
            material.addProperty("alphaMode", "BLEND");
        } else if (hasImage) {
            // Texture transparency is all or nothing in game: the renderer
            // discards fully transparent texels rather than blending them.
            material.addProperty("alphaMode", "MASK");
            material.addProperty("alphaCutoff", 0.5f);
        } else {
            material.addProperty("alphaMode", "OPAQUE");
        }

        // Neither scrolling UVs nor a depth bias is something glTF can express,
        // so both ride along as metadata for a renderer that knows to look.
        final JsonObject runeprofile = new JsonObject();
        if (hasImage && texture.isAnimated()) {
            runeprofile.addProperty("textureId", texture.getId());
            runeprofile.addProperty("scrollU", texture.getScrollU());
            runeprofile.addProperty("scrollV", texture.getScrollV());
        }
        if (runeprofile.size() > 0) {
            final JsonObject extras = new JsonObject();
            extras.add("runeprofile", runeprofile);
            material.add("extras", extras);
        }

        return material;
    }

    private static JsonObject unlitExtension() {
        final JsonObject extensions = new JsonObject();
        extensions.add("KHR_materials_unlit", new JsonObject());
        return extensions;
    }

    private static JsonObject buildTexture(int imageIndex) {
        final JsonObject texture = new JsonObject();
        texture.addProperty("sampler", 0);
        texture.addProperty("source", imageIndex);
        return texture;
    }

    private static JsonObject buildImage(GameTextures.TextureData texture, Options options,
                                         JsonArray bufferViews, BinaryChunk bin) throws IOException {
        final JsonObject image = new JsonObject();
        image.addProperty("name", "texture-" + texture.getId());
        if (options.embedTextures) {
            image.addProperty("bufferView", addBufferView(bufferViews, bin, texture.getPng(), -1, 0));
            image.addProperty("mimeType", "image/png");
        } else {
            image.addProperty("uri", String.format(options.textureUrlTemplate, texture.getId()));
        }
        return image;
    }

    private static JsonObject buildSampler() {
        final JsonObject sampler = new JsonObject();
        // Nearest magnification keeps the chunky look the game has; mipmapped
        // minification stops distant textures shimmering.
        sampler.addProperty("magFilter", FILTER_NEAREST);
        sampler.addProperty("minFilter", FILTER_LINEAR_MIPMAP_LINEAR);
        // Game UVs run outside 0..1 and rely on the texture repeating.
        sampler.addProperty("wrapS", WRAP_REPEAT);
        sampler.addProperty("wrapT", WRAP_REPEAT);
        return sampler;
    }

    private static int addAccessor(JsonArray bufferViews, JsonArray accessors, BinaryChunk bin,
                                   byte[] data, int target, int componentType, String type,
                                   int count, @Nullable float[] min, @Nullable float[] max,
                                   boolean normalized) throws IOException {
        final int bufferView = addBufferView(bufferViews, bin, data, target, 0);

        final JsonObject accessor = new JsonObject();
        accessor.addProperty("bufferView", bufferView);
        accessor.addProperty("componentType", componentType);
        accessor.addProperty("count", count);
        accessor.addProperty("type", type);
        if (normalized) {
            accessor.addProperty("normalized", true);
        }
        if (min != null) {
            accessor.add("min", jsonArray(min));
        }
        if (max != null) {
            accessor.add("max", jsonArray(max));
        }
        accessors.add(accessor);
        return accessors.size() - 1;
    }

    private static int addBufferView(JsonArray bufferViews, BinaryChunk bin, byte[] data,
                                     int target, int byteStride) throws IOException {
        final int offset = bin.append(data);

        final JsonObject bufferView = new JsonObject();
        bufferView.addProperty("buffer", 0);
        bufferView.addProperty("byteOffset", offset);
        bufferView.addProperty("byteLength", data.length);
        if (byteStride > 0) {
            bufferView.addProperty("byteStride", byteStride);
        }
        if (target > 0) {
            bufferView.addProperty("target", target);
        }
        bufferViews.add(bufferView);
        return bufferViews.size() - 1;
    }

    private static byte[] floatsToBytes(float[] values) {
        final ByteBuffer buffer = ByteBuffer.allocate(values.length * 4).order(ByteOrder.LITTLE_ENDIAN);
        for (float value : values) {
            buffer.putFloat(value);
        }
        return buffer.array();
    }

    private static byte[] indicesToBytes(int[] indices, boolean wide) {
        final ByteBuffer buffer = ByteBuffer
                .allocate(indices.length * (wide ? 4 : 2))
                .order(ByteOrder.LITTLE_ENDIAN);
        for (int index : indices) {
            if (wide) {
                buffer.putInt(index);
            } else {
                buffer.putShort((short) index);
            }
        }
        return buffer.array();
    }

    private static JsonArray jsonArray(float... values) {
        final JsonArray array = new JsonArray();
        for (float value : values) {
            array.add(value);
        }
        return array;
    }

    private static JsonArray singletonArray(JsonObject value) {
        final JsonArray array = new JsonArray();
        array.add(value);
        return array;
    }

    /**
     * Wraps the JSON and binary payloads in the GLB container. Both chunks are
     * padded to a four byte boundary, JSON with spaces and binary with zeroes,
     * as the format requires.
     */
    private static byte[] assemble(String json, byte[] binary) {
        final byte[] jsonBytes = json.getBytes(StandardCharsets.UTF_8);
        final int jsonPadding = padding(jsonBytes.length);
        final int binaryPadding = padding(binary.length);

        final int jsonChunkLength = jsonBytes.length + jsonPadding;
        final int binaryChunkLength = binary.length + binaryPadding;
        final int totalLength = 12 + 8 + jsonChunkLength + 8 + binaryChunkLength;

        final ByteBuffer buffer = ByteBuffer.allocate(totalLength).order(ByteOrder.LITTLE_ENDIAN);
        buffer.putInt(GLB_MAGIC);
        buffer.putInt(GLB_VERSION);
        buffer.putInt(totalLength);

        buffer.putInt(jsonChunkLength);
        buffer.putInt(CHUNK_JSON);
        buffer.put(jsonBytes);
        for (int i = 0; i < jsonPadding; i++) {
            buffer.put((byte) ' ');
        }

        buffer.putInt(binaryChunkLength);
        buffer.putInt(CHUNK_BIN);
        buffer.put(binary);
        for (int i = 0; i < binaryPadding; i++) {
            buffer.put((byte) 0);
        }

        return buffer.array();
    }

    private static int padding(int length) {
        return (4 - (length % 4)) % 4;
    }

    /**
     * The single binary buffer every buffer view points into. Appends are kept
     * four byte aligned, which every accessor component type we emit requires.
     */
    private static final class BinaryChunk {
        private final ByteArrayOutputStream out = new ByteArrayOutputStream();

        int append(byte[] data) throws IOException {
            for (int i = padding(out.size()); i > 0; i--) {
                out.write(0);
            }
            final int offset = out.size();
            out.write(data);
            return offset;
        }

        int size() {
            return out.size();
        }

        byte[] toByteArray() {
            return out.toByteArray();
        }
    }
}

package com.runeprofile.modelexporter;

import lombok.NonNull;
import net.runelite.api.Model;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Turns a game {@link Model} into a {@link MeshData}, keeping the texture
 * mapping the old PLY exporter threw away.
 * <p>
 * The game gives us, per face, either a colour or a texture id plus a "texture
 * triangle": three vertices of the model itself that define the texture's
 * origin and its two axes. UV coordinates are recovered by projecting each face
 * vertex onto those axes, which is what the client's own GPU renderer does every
 * frame (see {@link #computeFaceUvs}).
 * <p>
 * Vertex colours mean different things on the two kinds of face. Untextured
 * faces carry a packed HSL colour. Textured faces carry a 7 bit lightness that
 * the renderer multiplies the sampled texel by, so those become greys and the
 * multiply happens again at draw time against the texture.
 */
public final class ModelMeshBuilder {
    /** Index by packed HSL to get RGB. Matches what the old PLY exporter used. */
    private static final int[] COLOR_PALETTE = JagexColor.createPalette(JagexColor.BRIGHTNESS_MIN);

    /** Lightness on a textured face is 7 bit; the renderer divides by this. */
    private static final float TEXTURE_LIGHT_MAX = 127f;

    /** A third face colour of -1 means flat shading rather than a colour per corner. */
    private static final int FLAT_SHADED = -1;

    /**
     * A third face colour of -2 marks a face the game never draws, distinct from
     * -1 which only means flat shading. Skipping it is not an optimisation: the
     * value is a sentinel, so reading it as a colour index lands on hue 63,
     * saturation 7, luminance 126, and the face appears as a stray near white
     * triangle across the model. Missing this is why one showed over the top of
     * an inferno cape in both this exporter and the older PLY one.
     */
    private static final int HIDDEN_FACE = -2;

    /**
     * Game model space is X east, Y down, Z north. Since X cross Y equals Z it is
     * already right handed, same as glTF, so getting Y pointing up is a rotation
     * rather than a mirror: negate Y and Z, which is a 180 degree turn about X.
     * Negating Y alone would reflect the model, putting the character back to
     * front and swapping its handedness.
     * <p>
     * Because the mapping is a proper rotation its determinant is +1, so face
     * winding carries over unchanged and corners are emitted in their original
     * order.
     */
    private static final float[] AXIS_SIGNS = {1f, -1f, -1f};

    private ModelMeshBuilder() {
    }

    public static MeshData build(@NonNull Model model) {
        final Map<FaceGroup, List<Integer>> groups = groupFaces(model);
        final boolean textured = groups.keySet().stream().anyMatch(FaceGroup::isTextured);

        final VertexBuffer vertices = new VertexBuffer(model.getFaceCount(), textured,
                model.getFaceRenderPriorities() != null);
        final List<MeshData.Primitive> primitives = new ArrayList<>(groups.size());

        for (Map.Entry<FaceGroup, List<Integer>> entry : groups.entrySet()) {
            final FaceGroup group = entry.getKey();
            final int start = vertices.indexCount();

            for (int face : entry.getValue()) {
                appendFace(model, face, group.isTextured(), vertices);
            }

            primitives.add(new MeshData.Primitive(group.textureId, start,
                    vertices.indexCount() - start, group.translucent));
        }

        return vertices.toMeshData(primitives);
    }

    /**
     * Buckets the faces the game would actually draw, one bucket per primitive.
     * <p>
     * A {@link TreeMap} keeps the buckets in {@link FaceGroup}'s order, so the
     * same model always exports byte for byte the same.
     */
    private static Map<FaceGroup, List<Integer>> groupFaces(Model model) {
        final int[] colors3 = model.getFaceColors3();
        final short[] faceTextures = model.getFaceTextures();
        final byte[] faceTransparencies = model.getFaceTransparencies();

        final Map<FaceGroup, List<Integer>> groups = new TreeMap<>();
        for (int face = 0; face < model.getFaceCount(); face++) {
            if (colors3[face] == HIDDEN_FACE) {
                continue;
            }
            final int alpha = alphaOf(faceTransparencies, face);
            if (alpha == 0) {
                // Fully transparent: the game does not draw it, so neither do we.
                continue;
            }

            final int textureId = faceTextures == null ? MeshData.NO_TEXTURE : faceTextures[face];
            groups.computeIfAbsent(new FaceGroup(textureId, alpha != 255),
                    key -> new ArrayList<>()).add(face);
        }
        return groups;
    }

    /** Appends one face's three corners, in their original winding. */
    private static void appendFace(Model model, int face, boolean textured, VertexBuffer vertices) {
        final float[] verticesX = model.getVerticesX();
        final float[] verticesY = model.getVerticesY();
        final float[] verticesZ = model.getVerticesZ();

        final int[] corners = {
                model.getFaceIndices1()[face],
                model.getFaceIndices2()[face],
                model.getFaceIndices3()[face],
        };

        // A flat shaded face has one colour for the whole triangle rather than
        // one per corner.
        final int[] colors3 = model.getFaceColors3();
        final boolean flat = colors3[face] == FLAT_SHADED;
        final int[] cornerColors = {
                model.getFaceColors1()[face],
                flat ? model.getFaceColors1()[face] : model.getFaceColors2()[face],
                flat ? model.getFaceColors1()[face] : colors3[face],
        };

        final float[] u = new float[3];
        final float[] v = new float[3];
        if (textured) {
            computeFaceUvs(model, face, u, v);
        }

        final int alpha = alphaOf(model.getFaceTransparencies(), face);
        final byte[] facePriorities = model.getFaceRenderPriorities();
        final int priority = facePriorities == null ? 0 : facePriorities[face] & 0xff;

        for (int corner = 0; corner < 3; corner++) {
            final int vertex = corners[corner];
            vertices.add(
                    verticesX[vertex] * AXIS_SIGNS[0],
                    verticesY[vertex] * AXIS_SIGNS[1],
                    verticesZ[vertex] * AXIS_SIGNS[2],
                    textured
                            ? lightnessToGrey(cornerColors[corner])
                            : COLOR_PALETTE[cornerColors[corner] & 0xffff],
                    alpha,
                    textured ? u[corner] : 0f,
                    textured ? v[corner] : 0f,
                    priority);
        }
    }

    /** Face transparency is 0 for opaque, 255 for invisible; alpha is the inverse. */
    private static int alphaOf(byte[] faceTransparencies, int face) {
        if (faceTransparencies == null) {
            return 255;
        }
        return 255 - (faceTransparencies[face] & 0xff);
    }

    /**
     * A textured face's "colour" is a 7 bit lightness the renderer multiplies the
     * texel by. Expanding it to a grey lets an ordinary vertex colour multiply
     * reproduce the same shading.
     */
    private static int lightnessToGrey(int lightness) {
        final int clamped = lightness < 0 ? 0 : Math.min(lightness, (int) TEXTURE_LIGHT_MAX);
        final int level = Math.round(clamped / TEXTURE_LIGHT_MAX * 255f);
        return (level << 16) | (level << 8) | level;
    }

    /**
     * Projects a face's three vertices onto its texture triangle to recover UV
     * coordinates, mirroring {@code ModelUploader.computeFaceUvs} in the client's
     * GPU plugin so exported models are mapped exactly as the game maps them.
     * <p>
     * The texture triangle is three model vertices: the first is the texture's
     * origin, the other two are the ends of its U and V axes. Faces without one
     * fall back to mapping the triangle straight onto the texture's corner.
     */
    static void computeFaceUvs(Model model, int face, float[] u, float[] v) {
        final byte[] textureFaces = model.getTextureFaces();
        if (textureFaces == null || textureFaces[face] == -1) {
            u[0] = 0f;
            v[0] = 0f;
            u[1] = 1f;
            v[1] = 0f;
            u[2] = 0f;
            v[2] = 1f;
            return;
        }

        final float[] vertexX = model.getVerticesX();
        final float[] vertexY = model.getVerticesY();
        final float[] vertexZ = model.getVerticesZ();

        final int triangleA = model.getFaceIndices1()[face];
        final int triangleB = model.getFaceIndices2()[face];
        final int triangleC = model.getFaceIndices3()[face];

        final int textureFace = textureFaces[face] & 0xff;
        final int texA = model.getTexIndices1()[textureFace];
        final int texB = model.getTexIndices2()[textureFace];
        final int texC = model.getTexIndices3()[textureFace];

        // Texture origin, then its two axes as vectors from that origin.
        final float originX = vertexX[texA];
        final float originY = vertexY[texA];
        final float originZ = vertexZ[texA];

        final float axisUx = vertexX[texB] - originX;
        final float axisUy = vertexY[texB] - originY;
        final float axisUz = vertexZ[texB] - originZ;

        final float axisVx = vertexX[texC] - originX;
        final float axisVy = vertexY[texC] - originY;
        final float axisVz = vertexZ[texC] - originZ;

        // The face's own corners, relative to the same origin.
        final float aX = vertexX[triangleA] - originX;
        final float aY = vertexY[triangleA] - originY;
        final float aZ = vertexZ[triangleA] - originZ;

        final float bX = vertexX[triangleB] - originX;
        final float bY = vertexY[triangleB] - originY;
        final float bZ = vertexZ[triangleB] - originZ;

        final float cX = vertexX[triangleC] - originX;
        final float cY = vertexY[triangleC] - originY;
        final float cZ = vertexZ[triangleC] - originZ;

        // normal = axisU x axisV
        final float normalX = axisUy * axisVz - axisUz * axisVy;
        final float normalY = axisUz * axisVx - axisUx * axisVz;
        final float normalZ = axisUx * axisVy - axisUy * axisVx;

        // Projecting along axisV x normal isolates the U component, and the
        // reciprocal dot with axisU normalises it so axisU's end lands on u = 1.
        float projX = axisVy * normalZ - axisVz * normalY;
        float projY = axisVz * normalX - axisVx * normalZ;
        float projZ = axisVx * normalY - axisVy * normalX;
        float scale = 1.0F / (projX * axisUx + projY * axisUy + projZ * axisUz);

        u[0] = (projX * aX + projY * aY + projZ * aZ) * scale;
        u[1] = (projX * bX + projY * bY + projZ * bZ) * scale;
        u[2] = (projX * cX + projY * cY + projZ * cZ) * scale;

        // Same again with the axes swapped, for V.
        projX = axisUy * normalZ - axisUz * normalY;
        projY = axisUz * normalX - axisUx * normalZ;
        projZ = axisUx * normalY - axisUy * normalX;
        scale = 1.0F / (projX * axisVx + projY * axisVy + projZ * axisVz);

        v[0] = (projX * aX + projY * aY + projZ * aZ) * scale;
        v[1] = (projX * bX + projY * bY + projZ * bZ) * scale;
        v[2] = (projX * cX + projY * cY + projZ * cZ) * scale;
    }

    /**
     * Identifies which primitive a face belongs to: the two things that need a
     * separate material. Ordering puts untextured before textured and opaque
     * before translucent.
     * <p>
     * Nothing else belongs here. Splitting is not free - every extra primitive
     * is another mesh, and translucent triangles can only be ordered against
     * each other while they share one - so per face data a renderer needs is
     * carried per vertex instead.
     */
    private static final class FaceGroup implements Comparable<FaceGroup> {
        private final int textureId;
        private final boolean translucent;

        FaceGroup(int textureId, boolean translucent) {
            this.textureId = textureId;
            this.translucent = translucent;
        }

        boolean isTextured() {
            return textureId != MeshData.NO_TEXTURE;
        }

        @Override
        public int compareTo(FaceGroup other) {
            if (textureId != other.textureId) {
                return Integer.compare(textureId, other.textureId);
            }
            return translucent == other.translucent ? 0 : (translucent ? 1 : -1);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof FaceGroup)) {
                return false;
            }
            final FaceGroup other = (FaceGroup) o;
            return textureId == other.textureId && translucent == other.translucent;
        }

        @Override
        public int hashCode() {
            return textureId * 2 + (translucent ? 1 : 0);
        }
    }

    /**
     * Collects vertices as faces are appended, merging any that come out
     * identical, and tracks the bounds glTF wants on the position accessor.
     * <p>
     * Sized for the worst case of three unshared vertices per face and trimmed
     * at the end, which avoids growing four parallel buffers as it goes.
     */
    private static final class VertexBuffer {
        private final float[] positions;
        private final byte[] colors;
        private final float[] uvs;
        private final float[] priorities;
        private final int[] indices;
        private final Map<VertexKey, Integer> lookup;

        private final float[] min = {Float.MAX_VALUE, Float.MAX_VALUE, Float.MAX_VALUE};
        private final float[] max = {-Float.MAX_VALUE, -Float.MAX_VALUE, -Float.MAX_VALUE};

        private int vertexCount;
        private int indexCount;

        VertexBuffer(int faceCount, boolean textured, boolean prioritised) {
            final int capacity = faceCount * 3;
            this.positions = new float[capacity * 3];
            this.colors = new byte[capacity * 4];
            this.uvs = textured ? new float[capacity * 2] : null;
            this.priorities = prioritised ? new float[capacity] : null;
            this.indices = new int[capacity];
            this.lookup = new HashMap<>(capacity * 2);
        }

        int indexCount() {
            return indexCount;
        }

        void add(float x, float y, float z, int rgb, int alpha, float u, float v, int priority) {
            final VertexKey key = new VertexKey(x, y, z, rgb, alpha, u, v, priority);
            Integer slot = lookup.get(key);
            if (slot == null) {
                slot = vertexCount++;
                positions[slot * 3] = x;
                positions[slot * 3 + 1] = y;
                positions[slot * 3 + 2] = z;

                colors[slot * 4] = (byte) ((rgb >> 16) & 0xff);
                colors[slot * 4 + 1] = (byte) ((rgb >> 8) & 0xff);
                colors[slot * 4 + 2] = (byte) (rgb & 0xff);
                colors[slot * 4 + 3] = (byte) alpha;

                if (uvs != null) {
                    uvs[slot * 2] = u;
                    uvs[slot * 2 + 1] = v;
                }

                if (priorities != null) {
                    priorities[slot] = priority;
                }

                grow(x, 0);
                grow(y, 1);
                grow(z, 2);

                lookup.put(key, slot);
            }
            indices[indexCount++] = slot;
        }

        private void grow(float value, int axis) {
            if (value < min[axis]) {
                min[axis] = value;
            }
            if (value > max[axis]) {
                max[axis] = value;
            }
        }

        MeshData toMeshData(List<MeshData.Primitive> primitives) {
            if (vertexCount == 0) {
                final float[] origin = {0f, 0f, 0f};
                return new MeshData(new float[0], new byte[0], null, null, new int[0],
                        new ArrayList<>(), origin, origin);
            }
            return new MeshData(
                    trim(positions, vertexCount * 3),
                    trim(colors, vertexCount * 4),
                    priorities == null ? null : trim(priorities, vertexCount),
                    uvs == null ? null : trim(uvs, vertexCount * 2),
                    trim(indices, indexCount),
                    primitives,
                    min,
                    max);
        }

        private static float[] trim(float[] source, int length) {
            if (source.length == length) {
                return source;
            }
            final float[] trimmed = new float[length];
            System.arraycopy(source, 0, trimmed, 0, length);
            return trimmed;
        }

        private static byte[] trim(byte[] source, int length) {
            if (source.length == length) {
                return source;
            }
            final byte[] trimmed = new byte[length];
            System.arraycopy(source, 0, trimmed, 0, length);
            return trimmed;
        }

        private static int[] trim(int[] source, int length) {
            if (source.length == length) {
                return source;
            }
            final int[] trimmed = new int[length];
            System.arraycopy(source, 0, trimmed, 0, length);
            return trimmed;
        }
    }

    /**
     * Identity of a vertex for merging. Two face corners collapse into one vertex
     * only when position, colour and UV all agree, so flat shaded faces keep
     * their hard colour edges and textured faces keep their seams.
     */
    private static final class VertexKey {
        private final float x, y, z, u, v;
        private final int rgb, alpha, priority;
        private final int hash;

        VertexKey(float x, float y, float z, int rgb, int alpha, float u, float v, int priority) {
            this.x = x;
            this.y = y;
            this.z = z;
            this.rgb = rgb;
            this.alpha = alpha;
            this.u = u;
            this.v = v;
            this.priority = priority;

            int h = Float.floatToIntBits(x);
            h = h * 31 + Float.floatToIntBits(y);
            h = h * 31 + Float.floatToIntBits(z);
            h = h * 31 + rgb;
            h = h * 31 + alpha;
            h = h * 31 + Float.floatToIntBits(u);
            h = h * 31 + Float.floatToIntBits(v);
            h = h * 31 + priority;
            this.hash = h;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof VertexKey)) {
                return false;
            }
            final VertexKey other = (VertexKey) o;
            return hash == other.hash
                    && Float.floatToIntBits(x) == Float.floatToIntBits(other.x)
                    && Float.floatToIntBits(y) == Float.floatToIntBits(other.y)
                    && Float.floatToIntBits(z) == Float.floatToIntBits(other.z)
                    && rgb == other.rgb
                    && alpha == other.alpha
                    && Float.floatToIntBits(u) == Float.floatToIntBits(other.u)
                    && Float.floatToIntBits(v) == Float.floatToIntBits(other.v)
                    && priority == other.priority;
        }

        @Override
        public int hashCode() {
            return hash;
        }
    }
}

package com.runeprofile.modelexporter;

import java.util.Collections;
import java.util.List;

/**
 * A triangle mesh in a form that is independent of both the game's model
 * representation and the file format it will be written to.
 * <p>
 * There is a single shared vertex buffer and a single shared index buffer.
 * Each {@link Primitive} owns a contiguous run of that index buffer and names
 * the two things that decide how it is drawn: the game texture its triangles
 * are mapped to, and whether they are translucent. A model that mixes an
 * untextured body with, say, an inferno cape becomes two primitives over one
 * set of vertices rather than two meshes.
 * <p>
 * Everything else a renderer needs travels per vertex, so it never forces a
 * split. Face render priority is the reason that matters: translucent geometry
 * has to share one mesh to be sorted, so anything carried per primitive would
 * reach opaque faces only.
 * <p>
 * Faces are deliberately kept in as few primitives as they can be. Each one is
 * a separate mesh to a renderer, and translucent triangles can only be ordered
 * correctly against each other while they share one.
 * <p>
 * Coordinates are already in glTF's space: Y up, right handed, still in game
 * units (roughly 128 per tile), with index order wound counter clockwise.
 */
public final class MeshData {
    /** Texture id used by {@link Primitive#getTextureId()} for untextured triangles. */
    public static final int NO_TEXTURE = -1;

    /**
     * One run of triangles sharing a texture. {@code indexOffset} and
     * {@code indexCount} address {@link MeshData#getIndices()}.
     */
    public static final class Primitive {
        private final int textureId;
        private final int indexOffset;
        private final int indexCount;
        private final boolean translucent;

        Primitive(int textureId, int indexOffset, int indexCount, boolean translucent) {
            this.textureId = textureId;
            this.indexOffset = indexOffset;
            this.indexCount = indexCount;
            this.translucent = translucent;
        }

        public int getTextureId() {
            return textureId;
        }

        public int getIndexOffset() {
            return indexOffset;
        }

        public int getIndexCount() {
            return indexCount;
        }

        /** True when any triangle in the run is partially transparent. */
        public boolean isTranslucent() {
            return translucent;
        }




        public boolean isTextured() {
            return textureId != NO_TEXTURE;
        }
    }

    private final float[] positions;
    private final byte[] colors;
    private final float[] priorities;
    private final float[] uvs;
    private final int[] indices;
    private final List<Primitive> primitives;
    private final float[] min;
    private final float[] max;

    MeshData(float[] positions, byte[] colors, float[] priorities, float[] uvs, int[] indices,
             List<Primitive> primitives, float[] min, float[] max) {
        this.positions = positions;
        this.colors = colors;
        this.priorities = priorities;
        this.uvs = uvs;
        this.indices = indices;
        this.primitives = Collections.unmodifiableList(primitives);
        this.min = min;
        this.max = max;
    }

    /** Three floats per vertex. */
    public float[] getPositions() {
        return positions;
    }

    /** Four unsigned bytes per vertex, RGBA. */
    public byte[] getColors() {
        return colors;
    }

    /** Two floats per vertex, or null when no primitive is textured. */
    public float[] getUvs() {
        return uvs;
    }

    /**
     * One float per vertex: the game's face render priority, or null when the
     * model has none.
     * <p>
     * Per vertex rather than per primitive because a renderer needs it on
     * translucent geometry too, and translucent faces have to share one mesh so
     * their triangles can be sorted against each other. Carrying it on the
     * material would force a split that transparency cannot afford, and would
     * silently apply to opaque geometry only - which reorders opaque against
     * translucent and puts an arm through a crystal shield.
     */
    public float[] getPriorities() {
        return priorities;
    }

    public int[] getIndices() {
        return indices;
    }

    public List<Primitive> getPrimitives() {
        return primitives;
    }

    public int getVertexCount() {
        return positions.length / 3;
    }

    /** Per axis minimum of {@link #getPositions()}; glTF requires it on the position accessor. */
    public float[] getMin() {
        return min;
    }

    public float[] getMax() {
        return max;
    }

    public boolean isEmpty() {
        return indices.length == 0;
    }
}

package com.runeprofile.modelexporter;

import com.google.gson.Gson;
import lombok.NonNull;
import net.runelite.api.Client;
import net.runelite.api.Model;

import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Exports a game {@link Model} as a binary glTF.
 */
public final class GlbExporter {
    private GlbExporter() {
    }

    /**
     * Writes a self contained GLB with every texture embedded. One file, opens
     * in any glTF viewer, no external requests.
     */
    public static byte[] toBytes(@NonNull Gson gson, @NonNull Client client, @NonNull Model model,
                                 @NonNull String name) throws IOException {
        return toBytes(gson, client, model, new GlbWriter.Options().embedTextures().modelName(name));
    }

    public static byte[] toBytes(@NonNull Gson gson, @NonNull Client client, @NonNull Model model,
                                 @NonNull GlbWriter.Options options) throws IOException {
        final MeshData mesh = ModelMeshBuilder.build(model);
        final GameTextures textures = new GameTextures(client);

        final Map<String, Object> extras = new LinkedHashMap<>();
        extras.put("source", "runeprofile-plugin");
        extras.put("faceCount", model.getFaceCount());
        extras.put("vertexCount", mesh.getVertexCount());
        options.extras(extras);

        return GlbWriter.write(gson, mesh, textures::get, options);
    }
}

package com.runeprofile.modelexporter;

import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Texture;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

/**
 * Reads game textures out of the client as PNGs, along with the scroll rate
 * that makes animated ones (an inferno cape's fire, lava, water) move.
 * <p>
 * Encoded PNGs are cached for the life of the client: there are only a couple
 * of hundred textures in the game and a player uses a handful, but a profile
 * sync would otherwise re-encode the same cape every time.
 */
@Slf4j
public final class GameTextures {
    /**
     * The client advances texture animation once per client tick, and shifts
     * UVs by speed/128 each time. Client ticks are 20ms, so this converts the
     * game's per tick step into UV units per second for a renderer that works
     * in wall clock time.
     */
    private static final float TICKS_PER_SECOND = 50f;
    private static final float TEXTURE_ANIM_UNIT = 1f / 128f;

    /** One texture, ready to embed or upload. */
    public static final class TextureData {
        private final int id;
        private final byte[] png;
        private final int averageColor;
        private final float scrollU;
        private final float scrollV;

        TextureData(int id, @Nullable byte[] png, int averageColor, float scrollU, float scrollV) {
            this.id = id;
            this.png = png;
            this.averageColor = averageColor;
            this.scrollU = scrollU;
            this.scrollV = scrollV;
        }

        public int getId() {
            return id;
        }

        /** Null if the pixels could not be encoded; fall back to {@link #getAverageColor()}. */
        @Nullable
        public byte[] getPng() {
            return png;
        }

        /**
         * Packed RGB mean of the non transparent texels. Used as a flat stand in
         * when the image itself is unavailable, which is what the old PLY
         * exporter did for every textured face.
         */
        public int getAverageColor() {
            return averageColor;
        }

        /** UV units per second, 0 when the texture does not animate. */
        public float getScrollU() {
            return scrollU;
        }

        public float getScrollV() {
            return scrollV;
        }

        public boolean isAnimated() {
            return scrollU != 0f || scrollV != 0f;
        }
    }

    private final Client client;
    private final Map<Integer, TextureData> cache = new HashMap<>();

    public GameTextures(@NonNull Client client) {
        this.client = client;
    }

    /**
     * Returns the texture, or null when the client has not loaded it yet (its
     * pixels are fetched lazily, so a texture the local player has never had
     * on screen may genuinely be unavailable).
     */
    @Nullable
    public TextureData get(int textureId) {
        if (textureId < 0) {
            return null;
        }
        if (cache.containsKey(textureId)) {
            return cache.get(textureId);
        }

        TextureData data = load(textureId);
        cache.put(textureId, data);
        return data;
    }

    @Nullable
    private TextureData load(int textureId) {
        final int[] pixels;
        try {
            pixels = client.getTextureProvider().load(textureId);
        } catch (RuntimeException e) {
            log.debug("Could not load texture {}", textureId, e);
            return null;
        }

        if (pixels == null || pixels.length == 0) {
            return null;
        }

        // Textures are square; the client uses 128x128 but deriving it keeps
        // this working if that ever changes.
        final int size = (int) Math.round(Math.sqrt(pixels.length));
        if (size * size != pixels.length) {
            log.debug("Texture {} is not square ({} pixels)", textureId, pixels.length);
            return null;
        }

        byte[] png = null;
        try {
            png = encodePng(pixels, size);
        } catch (IOException | RuntimeException e) {
            // Still worth returning the average colour so the model renders as
            // a plausible flat surface rather than grey.
            log.debug("Could not encode texture {}", textureId, e);
        }

        final float[] scroll = scrollOf(textureId);
        return new TextureData(textureId, png, averageColor(pixels), scroll[0], scroll[1]);
    }

    /** Mean of every texel the game actually draws, ignoring transparent ones. */
    private static int averageColor(int[] pixels) {
        long red = 0;
        long green = 0;
        long blue = 0;
        int counted = 0;
        for (int pixel : pixels) {
            if (pixel == 0) {
                continue;
            }
            red += (pixel >> 16) & 0xff;
            green += (pixel >> 8) & 0xff;
            blue += pixel & 0xff;
            counted++;
        }
        if (counted == 0) {
            return 0xffffff;
        }
        return (int) ((red / counted) << 16 | (green / counted) << 8 | (blue / counted));
    }

    /**
     * A pixel of 0 is the game's transparent texel, which the renderer discards
     * rather than drawing black, so it becomes a fully transparent PNG pixel.
     */
    private static byte[] encodePng(int[] pixels, int size) throws IOException {
        final int[] argb = new int[pixels.length];
        for (int i = 0; i < pixels.length; i++) {
            final int rgb = pixels[i];
            argb[i] = rgb == 0 ? 0 : 0xff000000 | rgb;
        }

        final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        image.setRGB(0, 0, size, size, argb, 0, size);

        final ByteArrayOutputStream out = new ByteArrayOutputStream();
        ImageIO.write(image, "png", out);
        return out.toByteArray();
    }

    /**
     * Direction and speed come straight off the texture definition; the mapping
     * from direction to axis matches the client's own
     * {@code TextureManager.computeTextureAnimations}.
     */
    private float[] scrollOf(int textureId) {
        final Texture[] textures = client.getTextureProvider().getTextures();
        if (textures == null || textureId >= textures.length || textures[textureId] == null) {
            return new float[]{0f, 0f};
        }

        final Texture texture = textures[textureId];
        float u = 0f;
        float v = 0f;
        switch (texture.getAnimationDirection()) {
            case 1:
                v = -1f;
                break;
            case 2:
                u = -1f;
                break;
            case 3:
                v = 1f;
                break;
            case 4:
                u = 1f;
                break;
            default:
                return new float[]{0f, 0f};
        }

        final float perSecond = texture.getAnimationSpeed() * TEXTURE_ANIM_UNIT * TICKS_PER_SECOND;
        return new float[]{u * perSecond, v * perSecond};
    }
}

