import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import lombok.NonNull;
import lombok.experimental.UtilityClass;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;
import net.runelite.client.util.Text;
import okhttp3.*;

import javax.swing.*;
import java.awt.*;
import java.io.IOException;
import java.io.Reader;
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.time.LocalDateTime;
import java.time.OffsetDateTime;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.concurrent.CompletableFuture;
import java.util.function.Function;

@UtilityClass
public class Utils {
    // Code from: DinkPlugin
    // Repository: https://github.com/pajlads/DinkPlugin
    // License: BSD 2-Clause License
    public <T> CompletableFuture<T> readJson(@NonNull OkHttpClient httpClient, @NonNull Gson gson, @NonNull String url, @NonNull TypeToken<T> type) {
        return readUrl(httpClient, url, reader -> gson.fromJson(reader, type.getType()));
    }

    // Code from: DinkPlugin
    // Repository: https://github.com/pajlads/DinkPlugin
    // License: BSD 2-Clause License
    public <T> CompletableFuture<T> readUrl(@NonNull OkHttpClient httpClient, @NonNull String url, @NonNull Function<Reader, T> transformer) {
        CompletableFuture<T> future = new CompletableFuture<>();
        Request request = new Request.Builder().url(url).build();
        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NonNull Call call, @NonNull IOException e) {
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(@NonNull Call call, @NonNull Response response) {
                assert response.body() != null;
                try (Reader reader = response.body().charStream()) {
                    future.complete(transformer.apply(reader));
                } catch (Exception e) {
                    future.completeExceptionally(e);
                } finally {
                    response.close();
                }
            }
        });
        return future;
    }

    // Code from: DinkPlugin
    // Repository: https://github.com/pajlads/DinkPlugin
    // License: BSD 2-Clause License
    public String sanitize(String str) {
        if (str == null || str.isEmpty()) return "";
        return Text.removeTags(str.replace("<br>", "\n")).replace('\u00A0', ' ').trim();
    }

    public void openProfileInBrowser(String username) {
        String url = "https://www.runeprofile.com/" + username.replace(" ", "%20");
        LinkBrowser.browse(url);
    }

    public String getApiErrorMessage(Throwable ex, String defaultMessage) {
        String result = defaultMessage;

        if (ex instanceof RuneProfileApiException) {
            result = ex.getMessage();
        } else if (ex.getCause() instanceof RuneProfileApiException) {
            result = ex.getCause().getMessage();
        }

        return result;
    }

    /**
     * Formats an API timestamp (Postgres "yyyy-MM-dd HH:mm:ss[.SSSSSS]" in UTC,
     * or ISO-8601) for display. Falls back to the raw string if parsing fails.
     */
    public String formatTimestamp(String raw) {
        if (raw == null || raw.isEmpty()) return "";

        DateTimeFormatter displayFormat = DateTimeFormatter.ofPattern("MMM d, yyyy");
        String normalized = raw.trim().replace(' ', 'T');

        try {
            return OffsetDateTime.parse(normalized)
                    .atZoneSameInstant(ZoneId.systemDefault())
                    .format(displayFormat);
        } catch (DateTimeParseException ignored) {
            // no offset in the string, assume UTC
        }

        try {
            return LocalDateTime.parse(normalized)
                    .atOffset(ZoneOffset.UTC)
                    .atZoneSameInstant(ZoneId.systemDefault())
                    .format(displayFormat);
        } catch (DateTimeParseException e) {
            return raw;
        }
    }

    private final String[] QUANTITY_SUFFIXES = {"K", "M", "B", "T"};

    /**
     * Formats a quantity to three significant digits with a K/M/B/T suffix, e.g.
     * 1.23M or 15.6B. Rounds down so a value is never shown as more than it is.
     */
    public String formatQuantity(long quantity) {
        int suffix = -1;
        long divisor = 1;
        while (suffix < QUANTITY_SUFFIXES.length - 1 && quantity / divisor >= 1000) {
            divisor *= 1000;
            suffix++;
        }

        if (suffix < 0) {
            return Long.toString(quantity);
        }

        String digits = BigDecimal.valueOf(quantity)
                .divide(BigDecimal.valueOf(divisor))
                .round(new MathContext(3, RoundingMode.DOWN))
                .stripTrailingZeros()
                .toPlainString();
        return digits + QUANTITY_SUFFIXES[suffix];
    }

    /**
     * Multiline text that wraps at the component's actual width. Preferable over
     * width-constrained html labels, whose text can get clipped because the html
     * renderer measures the RuneScape fonts differently than they paint.
     */
    public JTextArea createParagraph(String text) {
        JTextArea area = new JTextArea();
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        area.setEditable(false);
        area.setFocusable(false);
        area.setOpaque(false);
        area.setBorder(null);
        area.setFont(FontManager.getRunescapeSmallFont());
        area.setForeground(Color.LIGHT_GRAY);
        setParagraphText(area, text);
        return area;
    }

    public void setParagraphText(JTextArea area, String text) {
        area.setText(text);
        // the line-wrapped preferred height is derived from the current width,
        // so give it a conservative width before the next layout
        area.setSize(PluginPanel.PANEL_WIDTH - 40, Short.MAX_VALUE);
        area.setMaximumSize(new Dimension(Short.MAX_VALUE, area.getPreferredSize().height));
    }

    public boolean isAccountNotFound(Throwable ex) {
        if (ex instanceof RuneProfileApiException) {
            return ((RuneProfileApiException) ex).isAccountNotFound();
        }
        if (ex.getCause() instanceof RuneProfileApiException) {
            return ((RuneProfileApiException) ex.getCause()).isAccountNotFound();
        }
        return false;
    }
}

package com.runeprofile.utils;


import lombok.NonNull;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;

import javax.annotation.Nullable;
import java.util.Map;

public class ItemUtils {
    public static final String ITEM_CACHE_BASE_URL = "https://static.runelite.net/cache/item/";

    /**
     * Default cutoff used until the manifest is loaded. The backend can override
     * this via the manifest.
     */
    public static final int VALUABLE_DROP_THRESHOLD = 1_000_000;

    public static int getUnnotedItemId(@NonNull ItemComposition comp) {
        return isItemNoted(comp) ? comp.getLinkedNoteId() : comp.getId();
    }

    /**
     * Resolves the value used to decide whether a drop is valuable. Items present
     * in {@code valueOverrides} (the special valuable drops served by the manifest)
     * use their fixed value; everything else uses the live GE price.
     */
    public static long getPerceivedItemValue(@NonNull ItemManager itemManager, int itemId, @Nullable Map<Integer, Integer> valueOverrides) {
        if (valueOverrides != null) {
            Integer override = valueOverrides.get(itemId);
            if (override != null) {
                return override;
            }
        }
        return itemManager.getItemPriceWithSource(itemId, true);
    }

    public static boolean isItemNoted(@NonNull ItemComposition item) {
        return item.getNote() != -1;
    }
}

package com.runeprofile.utils;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.runeprofile.RuneProfilePlugin;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import javax.swing.ImageIcon;
import java.io.ByteArrayInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * A classpath JSON map of base64-encoded PNGs (the shape produced by
 * the runeprofile repo's cache pipeline and shared with the website),
 * decoded to {@link ImageIcon}s
 * on demand and cached. The JSON is loaded lazily on first access.
 */
@Slf4j
public final class IconSheet {
    private final Gson gson;
    private final String resourcePath;

    private Map<String, String> base64ByKey;

    // Decoded icons, including null for missing keys, so each key is decoded once.
    private final Map<String, ImageIcon> cache = new HashMap<>();

    public IconSheet(@NonNull Gson gson, String resourcePath) {
        this.gson = gson;
        this.resourcePath = resourcePath;
    }

    /**
     * The icon for a key, or {@code null} when the key is absent or fails to decode.
     */
    public synchronized @Nullable ImageIcon get(@Nullable String key) {
        if (key == null) {
            return null;
        }
        if (cache.containsKey(key)) {
            return cache.get(key);
        }

        ImageIcon icon = decode(key);
        cache.put(key, icon);
        return icon;
    }

    private @Nullable ImageIcon decode(String key) {
        String base64 = base64ByKey().get(key);
        if (base64 == null) {
            return null;
        }
        try {
            byte[] bytes = Base64.getDecoder().decode(base64);
            return new ImageIcon(ImageIO.read(new ByteArrayInputStream(bytes)));
        } catch (Exception e) {
            log.debug("Failed to decode icon for key = {} in {}", key, resourcePath, e);
            return null;
        }
    }

    private Map<String, String> base64ByKey() {
        if (base64ByKey == null) {
            base64ByKey = load(gson, resourcePath);
        }
        return base64ByKey;
    }

    private static Map<String, String> load(Gson gson, String resourcePath) {
        try (InputStream in = RuneProfilePlugin.class.getResourceAsStream(resourcePath)) {
            if (in == null) {
                log.debug("Icon sheet not found on classpath: {}", resourcePath);
                return Collections.emptyMap();
            }
            try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                Map<String, String> icons = gson.fromJson(reader, new TypeToken<Map<String, String>>() {
                }.getType());
                return icons != null ? icons : Collections.emptyMap();
            }
        } catch (Exception e) {
            log.debug("Failed to load icon sheet: {}", resourcePath, e);
            return Collections.emptyMap();
        }
    }
}

