package com.runeprofile.utils;

import lombok.Getter;

import javax.annotation.Nullable;

@Getter
public class RuneProfileApiException extends RuntimeException {
    public static final String CODE_ACCOUNT_NOT_FOUND = "AccountNotFound";

    @Nullable
    private final String code;
    private final int statusCode;

    public RuneProfileApiException(String message) {
        this(message, null, -1);
    }

    public RuneProfileApiException(String message, @Nullable String code, int statusCode) {
        super(message);
        this.code = code;
        this.statusCode = statusCode;
    }

    public boolean isAccountNotFound() {
        return CODE_ACCOUNT_NOT_FOUND.equals(code) || statusCode == 404;
    }
}

package com.runeprofile.autosync;

import com.google.common.collect.ImmutableSet;
import com.runeprofile.RuneProfileConfig;
import com.runeprofile.utils.ItemSearcher;
import com.runeprofile.utils.PlayerState;
import com.runeprofile.utils.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class CollectionNotificationSubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private AutoSyncScheduler autoSyncScheduler;

    @Inject
    private PlayerDataService playerDataService;

    @Inject
    private ItemSearcher itemSearcher;

    private static final Pattern NEW_ITEM_REGEX = Pattern.compile("New item added to your collection log: (?<itemName>(.*))");
    private static final int POPUP_PREFIX_LENGTH = "New item:".length();

    private final AtomicBoolean popupStarted = new AtomicBoolean(false);

    // Items that can't be synced via collection log notifications because of non-unique names
    private final static Set<String> IGNORED_ITEMS = ImmutableSet.of(
            "Chompy bird hat",
            "Decorative sword",
            "Decorative armour",
            "Decorative helm",
            "Decorative shield",
            "Castlewars hood",
            "Castlewars cloak",
            "Rum",
            "Ancient page",
            "Graceful hood",
            "Graceful cape",
            "Graceful top",
            "Graceful legs",
            "Graceful gloves",
            "Graceful boots",
            "Mysterious page",
            "Decorative boots",
            "Decorative full helm",
            "Medallion fragment"
    );

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    private boolean isEnabled() {
        return config.autosyncProfile() && PlayerState.isValidPlayerState(client);
    }

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    public void reset() {
        popupStarted.set(false);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        GameState gameState = gameStateChanged.getGameState();
        if (gameState != GameState.HOPPING && gameState != GameState.LOGGED_IN) {
            reset();
        }
    }

    // Code from: DinkPlugin
    // Repository: https://github.com/pajlads/DinkPlugin
    // License: BSD 2-Clause License
    @Subscribe
    public void onChatMessage(ChatMessage chatMessage) {
        if (chatMessage.getType() != ChatMessageType.GAMEMESSAGE || client.getVarbitValue(VarbitID.OPTION_COLLECTION_NEW_ITEM) != 1 || !isEnabled()) {
            return;
        }

        Matcher matcher = NEW_ITEM_REGEX.matcher(chatMessage.getMessage());
        if (matcher.find()) {
            String itemName = matcher.group("itemName");
            handleAutosync(itemName);
            log.debug("Chat message found for new item: {}", itemName);
        }
    }

    // Code from: DinkPlugin
    // Repository: https://github.com/pajlads/DinkPlugin
    // License: BSD 2-Clause License
    @Subscribe
    public void onScriptPreFired(ScriptPreFired event) {
        final int scriptId = event.getScriptId();
        if (scriptId == ScriptID.NOTIFICATION_START) {
            popupStarted.set(true);
        } else if (scriptId == ScriptID.NOTIFICATION_DELAY) {
            String topText = client.getVarcStrValue(VarClientID.NOTIFICATION_TITLE);
            if (popupStarted.getAndSet(false) && "Collection log".equalsIgnoreCase(topText) && isEnabled()) {
                String bottomText = Utils.sanitize(client.getVarcStrValue(VarClientID.NOTIFICATION_MAIN));
                String itemName = bottomText.substring(POPUP_PREFIX_LENGTH).trim();
                handleAutosync(itemName);
                log.debug("Script fired for new item: {}", itemName);
            }
        }
    }

    private void handleAutosync(String itemName) {
        if (IGNORED_ITEMS.contains(itemName)) {
            log.debug("Ignoring collection log item with non-unique name: {}", itemName);
            return;
        }

        Integer itemId = itemSearcher.findItemId(itemName);
        if (itemId == null) {
            log.debug("Failed to find item ID for: {}", itemName);
            return;
        }
        playerDataService.storeItem(itemId, 1);
        autoSyncScheduler.startRapidSync("collection-notification");
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileConfig;
import com.runeprofile.utils.PlayerState;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class QuestCompletedSubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private AutoSyncScheduler autoSyncScheduler;

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        if (event.getGroupId() != InterfaceID.QUEST_COMPLETED) {
            return;
        }

        if (!config.autosyncProfile() || !PlayerState.isValidPlayerState(client)) {
            return;
        }

        // Delay by 1 tick to ensure quest varbits have settled
        clientThread.invokeLater(() -> {
            log.debug("Quest completion scroll detected, scheduling rapid sync");
            autoSyncScheduler.startRapidSync("quest-completed");
        });
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileConfig;
import com.runeprofile.utils.PlayerState;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class CombatAchievementSubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private AutoSyncScheduler autoSyncScheduler;

    private static final Pattern CA_TASK_COMPLETED_PATTERN = Pattern.compile(
            "Congratulations, you've completed an? (?:\\w+) combat task:"
    );

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE) {
            return;
        }

        if (!config.autosyncProfile() || !PlayerState.isValidPlayerState(client)) {
            return;
        }

        if (CA_TASK_COMPLETED_PATTERN.matcher(event.getMessage()).find()) {
            log.debug("Combat achievement task completed: {}", event.getMessage());
            autoSyncScheduler.startRapidSync("combat-achievement-completed");
        }
    }
}

package com.runeprofile.autosync;

import com.google.gson.Gson;
import com.runeprofile.RuneProfileConfig;
import com.runeprofile.data.*;
import com.runeprofile.modelexporter.GlbExporter;
import com.runeprofile.utils.AccountHash;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.clan.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.IOException;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;

@Slf4j
@Singleton
public class PlayerDataService {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private Gson gson;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private ManifestService manifestService;

    // Clog items are not available through the client API, so we store them manually on clog open or item collection.
    // See: CollectionLogWidgetSubscriber and CollectionNotificationSubscriber
    private final Map<Integer, Integer> clogItems = new HashMap<>();

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    public void reset() {
        clearItems();
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event) {
        log.debug("RuneScape Profile changed to {}, resetting player data service", event.getNewProfile());
        reset();
    }

    public void storeItem(int itemId, int quantity) {
        if (quantity <= 0) return;
        clogItems.put(itemId, quantity);
    }

    public void clearItems() {
        clogItems.clear();
    }

    public CompletableFuture<String> getAccountIdAsync() {
        CompletableFuture<String> accountIdFuture = new CompletableFuture<>();
        clientThread.invokeLater(() -> {
            String accountId = AccountHash.getHashed(client);
            accountIdFuture.complete(accountId);
        });
        return accountIdFuture;
    }

    public CompletableFuture<PlayerData> getPlayerDataAsync() {
        CompletableFuture<PlayerData> playerDataFuture = new CompletableFuture<>();
        clientThread.invokeLater(() -> {
            Manifest manifest = manifestService.getManifest();
            PlayerData playerData = new PlayerData();

            Player player = client.getLocalPlayer();

            playerData.setId(AccountHash.getHashed(client));
            playerData.setUsername(player.getName());
            playerData.setAccountType(client.getVarbitValue(VarbitID.IRONMAN));
            playerData.setClan(getPlayerClanData(player));
            playerData.setGroupName(getPlayerGroupName());
            playerData.setGimGroupSize(client.getVarbitValue(VarbitID.GIM_GROUPSIZE));

            collectSkills(playerData);
            collectQuests(playerData, manifest);
            collectCombatAchievementVarps(playerData, manifest);
            collectAchievementDiaryTiers(playerData);

            // Unlike the rest, clog items are accumulated as the player sees them
            // rather than read from the client here.
            playerData.setItems(clogItems);

            log.debug("Player Data: {}", playerData);
            playerDataFuture.complete(playerData);
        });
        return playerDataFuture;
    }

    private void collectSkills(PlayerData playerData) {
        for (Skill skill : Skill.values()) {
            playerData.getSkills().put(skill.getName(), client.getSkillExperience(skill));
        }
    }

    /**
     * Records the state of every quest the manifest lists, falling back to RuneLite's Quest enum.
     */
    private void collectQuests(PlayerData playerData, @Nullable Manifest manifest) {
        int[] questIds = manifest != null && manifest.getQuestIds().length > 0
                ? manifest.getQuestIds()
                : Arrays.stream(Quest.values()).mapToInt(Quest::getId).toArray();

        for (int questId : questIds) {
            try {
                // What Quest#getState does internally: the script leaves the status on the int stack.
                client.runScript(ScriptID.QUEST_STATUS_GET, questId);
                playerData.getQuests().put(questId, fromQuestStatus(client.getIntStack()[0]));
            } catch (Exception e) {
                log.debug("Unable to read state of quest {}: {}", questId, e.toString());
            }
        }
    }

    /** Maps a QUEST_STATUS_GET result to RuneProfile's state encoding. */
    private static int fromQuestStatus(int status) {
        // Same mapping Quest#getState applies: 1 is not started, 2 is finished, and
        // every other value means the quest is underway.
        if (status == 1) return 0;
        if (status == 2) return 2;
        return 1;
    }

    /** No-op without a manifest: the varps to read are only known from it. */
    private void collectCombatAchievementVarps(PlayerData playerData, @Nullable Manifest manifest) {
        if (manifest == null) return;

        for (int varpId : manifest.getCombatAchievementVarps()) {
            playerData.getCombatAchievementVarps().put(varpId, client.getVarpValue(varpId));
        }
    }

    private void collectAchievementDiaryTiers(PlayerData playerData) {
        for (AchievementDiary diary : AchievementDiary.values()) {
            int areaId = diary.getId();
            int[] completedCounts = diary.getTiersCompletedCount(client);
            for (int tierIndex = 0; tierIndex < completedCounts.length; tierIndex++) {
                playerData.getAchievementDiaryTiers()
                        .add(new AchievementDiaryTierData(areaId, tierIndex, completedCounts[tierIndex]));
            }
        }
    }

    public @Nullable PlayerClanData getPlayerClanData(Player player) {
        if (!config.includeClanData()) return new PlayerClanData("", -1, -1, "");

        ClanSettings clanSettings = client.getClanSettings();
        if (clanSettings == null) return new PlayerClanData("", -1, -1, ""); // not in a clan

        ClanMember member = clanSettings.findMember(player.getName());
        if (member == null) return null;

        ClanRank rank = member.getRank();
        if (rank == null) return null;

        ClanTitle title = clanSettings.titleForRank(rank);
        if (title == null) return null;

        return new PlayerClanData(clanSettings.getName(), rank.getRank(), title.getId(), title.getName());
    }

    public @Nullable String getPlayerGroupName() {
        ClanSettings clanSettings = client.getClanSettings(ClanID.GROUP_IRONMAN);
        if (clanSettings == null) return null;
        return clanSettings.getName();
    }

    public CompletableFuture<PlayerModelData> getPlayerModelDataAsync() {
        CompletableFuture<PlayerModelData> dataFuture = new CompletableFuture<>();
        clientThread.invokeLater(() -> {
            String accountHash = AccountHash.getHashed(client);

            Player player = client.getLocalPlayer();
            Model model = player != null ? player.getModel() : null;
            if (model == null) {
                dataFuture.completeExceptionally(new IllegalStateException("Player model is not available yet"));
                return;
            }

            byte[] modelBytes = null;
            try {
                modelBytes = GlbExporter.toBytes(gson, client, model, "player");
            } catch (IOException e) {
                dataFuture.completeExceptionally(e);
                return;
            }

            NPC pet = client.getFollower();
            Model petModel = pet != null ? pet.getModel() : null;

            byte[] petModelBytes = null;
            if (petModel != null) {
                try {
                    petModelBytes = GlbExporter.toBytes(gson, client, petModel, "pet");
                } catch (IOException e) {
                    dataFuture.completeExceptionally(e);
                    return;
                }
            }

            dataFuture.complete(new PlayerModelData(accountHash, modelBytes, petModelBytes));
        });
        return dataFuture;
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileConfig;
import com.runeprofile.utils.PlayerState;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.regex.Pattern;

@Slf4j
@Singleton
public class AchievementDiarySubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private AutoSyncScheduler autoSyncScheduler;

    private static final Pattern DIARY_COMPLETION_PATTERN = Pattern.compile(
            "Congratulations! You have completed all of the (?<difficulty>.+) tasks in the (?<area>.+) area"
    );

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.MESBOX) {
            return;
        }

        if (!config.autosyncProfile() || !PlayerState.isValidPlayerState(client)) {
            return;
        }

        if (DIARY_COMPLETION_PATTERN.matcher(event.getMessage()).find()) {
            log.debug("Achievement diary tier completion detected: {}", event.getMessage());
            autoSyncScheduler.startRapidSync("achievement-diary-completed");
        }
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileApiClient;
import com.runeprofile.RuneProfileConfig;
import com.runeprofile.RuneProfilePlugin;
import com.runeprofile.utils.AccountHash;
import com.runeprofile.utils.PlayerState;
import com.runeprofile.utils.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/**
 * Automatically creates a profile for accounts that don't have one yet.
 * On login (or plugin startup while already logged in), checks if the account
 * has a profile; if not, triggers an initial profile sync.
 */
@Slf4j
@Singleton
public class ProfileCreationService {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ScheduledExecutorService scheduledExecutorService;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private RuneProfileApiClient apiClient;

    @Inject
    private RuneProfilePlugin plugin;

    // Accounts already checked this session, so each account is only checked once
    private final Set<String> checkedAccountIds = ConcurrentHashMap.newKeySet();

    // Prevent overlapping existence checks
    private final AtomicBoolean checkInFlight = new AtomicBoolean(false);

    // Cooldown after a transient failure
    private static final long FAILED_CHECK_COOLDOWN_MILLIS = TimeUnit.MINUTES.toMillis(5);
    private volatile long lastFailedCheckAt;

    // Delay before the initial sync, so login-time data (clan channels, etc.) has loaded
    private static final int INITIAL_SYNC_DELAY_SECONDS = 60;

    // The scheduled initial sync, cancelled if the player logs out while waiting
    private ScheduledFuture<?> pendingInitialSync;
    private String pendingInitialSyncAccountId;

    public void startUp() {
        eventBus.register(this);
        // The plugin can be installed from the plugin hub while already logged in,
        // in which case no GameStateChanged event will fire - check right away.
        scheduleCheck(false);
    }

    public void shutDown() {
        eventBus.unregister(this);
        cancelPendingInitialSync();
        checkedAccountIds.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        GameState state = event.getGameState();
        if (state == GameState.LOGGED_IN) {
            // delay the initial sync, login-time data (clan channels, etc.) loads a while after login
            scheduleCheck(true);
        } else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING) {
            cancelPendingInitialSync();
        }
    }

    private synchronized void cancelPendingInitialSync() {
        if (pendingInitialSync == null) return;

        log.debug("Abandoning pending initial sync, player logged out");
        pendingInitialSync.cancel(false);
        pendingInitialSync = null;

        // allow the check to run again on the next login
        if (pendingInitialSyncAccountId != null) {
            checkedAccountIds.remove(pendingInitialSyncAccountId);
            pendingInitialSyncAccountId = null;
        }
    }

    private void scheduleCheck(boolean delayInitialSync) {
        if (!config.autosyncProfile()) return;

        clientThread.invokeLater(() -> {
            if (!PlayerState.isValidPlayerState(client)) return;

            String accountId = AccountHash.getHashed(client);
            if (accountId == null || checkedAccountIds.contains(accountId)) return;

            if (System.currentTimeMillis() - lastFailedCheckAt < FAILED_CHECK_COOLDOWN_MILLIS) return;

            if (!checkInFlight.compareAndSet(false, true)) return;

            checkProfileExists(accountId, delayInitialSync);
        });
    }

    private void checkProfileExists(String accountId, boolean delayInitialSync) {
        log.debug("Checking if a profile exists for the current account");
        apiClient.getAccountAsync(accountId).whenComplete((account, ex) -> {
            try {
                if (ex == null) {
                    log.debug("Profile already exists");
                    checkedAccountIds.add(accountId);
                    return;
                }

                if (Utils.isAccountNotFound(ex)) {
                    checkedAccountIds.add(accountId);
                    if (delayInitialSync) {
                        scheduleInitialSync(accountId);
                    } else {
                        runInitialSync(accountId);
                    }
                } else {
                    // Transient error: don't mark as checked, so it is retried
                    // on the next login (after the cooldown)
                    lastFailedCheckAt = System.currentTimeMillis();
                    log.warn("Profile existence check failed", ex);
                }
            } finally {
                checkInFlight.set(false);
            }
        });
    }

    /**
     * Schedules the initial profile sync a while after login, so login-time data
     * (clan channels, group ironman info, etc.) has had time to load. Abandoned
     * if the player logs out or switches accounts in the meantime, in which case
     * the check is re-armed for the next login.
     */
    private synchronized void scheduleInitialSync(String accountId) {
        log.debug("No profile found, scheduling initial sync in {} seconds", INITIAL_SYNC_DELAY_SECONDS);

        pendingInitialSyncAccountId = accountId;
        pendingInitialSync = scheduledExecutorService.schedule(() -> {
            synchronized (this) {
                pendingInitialSync = null;
                pendingInitialSyncAccountId = null;
            }
            runInitialSync(accountId);
        }, INITIAL_SYNC_DELAY_SECONDS, TimeUnit.SECONDS);
    }

    private void runInitialSync(String accountId) {
        clientThread.invokeLater(() -> {
            if (!PlayerState.isValidPlayerState(client) || !accountId.equals(AccountHash.getHashed(client))) {
                log.debug("Abandoning initial sync, player logged out or switched accounts");
                checkedAccountIds.remove(accountId);
                return;
            }

            try {
                plugin.updateProfileAsync(true, "initial-profile-creation");
            } catch (IllegalStateException stateEx) {
                log.warn("Could not run initial profile sync", stateEx);
            }
        });
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfilePlugin;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.events.*;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@Singleton
public class CollectionLogWidgetSubscriber {
    private static final int COLLECTION_DELAYED_TRANSMIT = 4100;
    private static final int COLLECTION_LOG_SETUP = 7797;
    private static final int COLLECTION_INIT_SCRIPT = 2240;

    @Inject
    private EventBus eventBus;

    @Inject
    private ScheduledExecutorService scheduledExecutorService;

    @Inject
    private Client client;

    @Inject
    private PlayerDataService playerDataService;

    @Inject
    private RuneProfilePlugin plugin;

    private boolean isManualSync = false;
    private boolean isAutoClogRetrieval = false;
    private int tickCollectionLogScriptFired = -1;

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    public void reset() {
        isManualSync = false;
        isAutoClogRetrieval = false;
        tickCollectionLogScriptFired = -1;
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        GameState gameState = gameStateChanged.getGameState();
        if (gameState != GameState.HOPPING && gameState != GameState.LOGGED_IN) {
            reset();
        }
    }

    // Code from: WikiSync
    // Repository: https://github.com/weirdgloop/WikiSync
    // License: BSD 2-Clause License
    @Subscribe
    public void onGameTick(GameTick gameTick) {
        int tick = client.getTickCount();
        boolean hasClogScriptFired = tickCollectionLogScriptFired != -1;
        boolean hasBufferPassed = tickCollectionLogScriptFired + 2 < tick;
        if (hasClogScriptFired && hasBufferPassed) {
            tickCollectionLogScriptFired = -1;
            log.debug("Clog items script has fired, is manual sync: {}", isManualSync);
            if (isManualSync) {
                scheduledExecutorService.execute(() -> plugin.updateProfileAsync(false, "manual-update-button-clog"));
                isManualSync = false;
            }
            isAutoClogRetrieval = false;
        }
    }

    // Code from: WikiSync
    // Repository: https://github.com/weirdgloop/WikiSync
    // License: BSD 2-Clause License
    @Subscribe
    public void onScriptPreFired(ScriptPreFired preFired) {
        if (preFired.getScriptId() != COLLECTION_DELAYED_TRANSMIT) {
            return;
        }

        // prevent reacting to scripts fired when opened from adventure log
        // e.g. other plugins might fire the collection log script when viewing other players' collection logs
        boolean isOpenedFromAdventureLog = client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
        if (isOpenedFromAdventureLog) {
            return;
        }

        tickCollectionLogScriptFired = client.getTickCount();

        Object[] args = preFired.getScriptEvent().getArguments();
        int itemId = (int) args[1];
        int quantity = (int) args[2];
        log.debug("Item id: {}, Quantity: {}", itemId, quantity);

        playerDataService.storeItem(itemId, quantity);
    }

    // When the collection log is opened, automatically make the server transmit every clog
    // entry so the full collection log is stored for the next auto-sync (no profile update is
    // triggered here). The menuAction "Search" op is what requests the data from the server;
    // re-running the collection log init script then resets the view, closing the search again.
    @Subscribe
    public void onScriptPostFired(ScriptPostFired scriptPostFired) {
        if (scriptPostFired.getScriptId() != COLLECTION_LOG_SETUP) {
            return;
        }

        // disallow retrieving from the adventure log, to avoid storing another player's
        // collection log while viewing it through the POH adventure log.
        boolean isOpenedFromAdventureLog = client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
        if (isOpenedFromAdventureLog) {
            playerDataService.clearItems();
            return;
        }

        // guard against re-triggering from the init script we run below (which re-fires setup)
        if (isAutoClogRetrieval) {
            return;
        }

        isAutoClogRetrieval = true;
        client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
        client.runScript(COLLECTION_INIT_SCRIPT);
    }

    public void triggerManualSync() {
        isManualSync = true;
    }

    // fail-safe to clear stored items if the collection log is opened from the adventure log
    @Subscribe
    public void onVarbitChanged(VarbitChanged varbitChanged) {
        if (varbitChanged.getVarbitId() == VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) {
            boolean isOpenedFromAdventureLog = client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
            if (isOpenedFromAdventureLog) {
                log.debug("Collection log opened from adventure log, clearing stored items to avoid incorrect updates.");
                playerDataService.clearItems();
            }
        }
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileApiClient;
import com.runeprofile.data.Manifest;
import lombok.extern.slf4j.Slf4j;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;

/**
 * Keeps a cached copy of the backend manifest. The manifest drives several
 * features (command suggestions, quest ids, combat achievement varps and the
 * special valuable-drop overrides), so it is refreshed for the lifetime of the
 * plugin regardless of individual feature toggles.
 * <p>
 * Each refresh schedules the next one rather than running at a fixed rate, so a
 * failed fetch can retry with exponential backoff instead of waiting out the
 * full hourly period.
 * <p>
 * Backoff is deliberately asymmetric. Until a manifest has been cached the
 * plugin is degraded - combat achievements and valuable-drop overrides are
 * skipped entirely, and quests fall back to RuneLite's Quest enum - so retries
 * start after a couple of seconds and never stretch beyond a few minutes. Once
 * a copy is cached the data is merely stale rather than missing, so retries
 * start slower and are allowed to grow into the normal hourly cadence.
 */
@Slf4j
@Singleton
public class ManifestService {
    private static final long REFRESH_MINUTES = 60;
    /**
     * First retry while no manifest is cached. The plugin is degraded until one
     * arrives, and the common failure here is a transient blip at login, so this
     * is short enough to recover before the player notices.
     */
    private static final long INITIAL_RETRY_WITHOUT_MANIFEST_SECONDS = 2;
    /** First retry once a manifest is cached: the copy is only stale, so there is no rush. */
    private static final long INITIAL_RETRY_WITH_MANIFEST_SECONDS = 30;
    /** Cap while no manifest is cached: keep trying to get the plugin to a working state. */
    private static final long MAX_RETRY_WITHOUT_MANIFEST_MINUTES = 5;
    /** Cap once a manifest is cached: settle back into the normal refresh cadence. */
    private static final long MAX_RETRY_WITH_MANIFEST_MINUTES = REFRESH_MINUTES;
    /** Fraction each delay is randomly stretched or shrunk by. */
    private static final double JITTER_RATIO = 0.25;
    /** Keeps the exponential shift well inside long range; the cap applies anyway. */
    private static final int MAX_BACKOFF_DOUBLINGS = 20;

    @Inject
    private ScheduledExecutorService scheduledExecutorService;

    @Inject
    private RuneProfileApiClient apiClient;

    private ScheduledFuture<?> manifestRefreshFuture;

    // Written on the HTTP callback thread, read from the client thread.
    private volatile Manifest cachedManifest;
    private volatile int consecutiveFailures;
    // Guards against an in-flight fetch rescheduling itself after shutDown().
    private volatile boolean running;

    public void startUp() {
        running = true;
        consecutiveFailures = 0;
        scheduleRefresh(0, TimeUnit.MILLISECONDS);
    }

    public void shutDown() {
        running = false;
        cancelScheduledRefresh();
    }

    private synchronized void scheduleRefresh(long delay, TimeUnit unit) {
        if (!running) return;
        cancelScheduledRefresh();
        manifestRefreshFuture = scheduledExecutorService.schedule(this::refreshManifest, delay, unit);
    }

    private synchronized void cancelScheduledRefresh() {
        if (manifestRefreshFuture != null) {
            // Not interrupting: the task only kicks off an async request, and the
            // in-flight fetch is already made harmless by the running flag.
            manifestRefreshFuture.cancel(false);
            manifestRefreshFuture = null;
        }
    }

    private void refreshManifest() {
        // whenComplete rather than thenAccept/exceptionally so that success and
        // failure share one handler and cannot both schedule a follow-up.
        apiClient.getManifest().whenComplete((manifest, ex) -> {
            if (ex != null) {
                onRefreshFailed(ex.toString());
                return;
            }
            if (manifest == null) {
                onRefreshFailed("API returned no manifest");
                return;
            }

            cachedManifest = manifest;
            consecutiveFailures = 0;
            log.debug("Manifest refreshed successfully (version {})", manifest.getVersion());
            scheduleRefresh(jitter(TimeUnit.MINUTES.toMillis(REFRESH_MINUTES)), TimeUnit.MILLISECONDS);
        });
    }

    private void onRefreshFailed(String reason) {
        consecutiveFailures++;
        long delayMillis = retryDelayMillis();
        log.debug("Failed to refresh manifest (attempt {}): {}. Retrying in {}s.",
                consecutiveFailures, reason, TimeUnit.MILLISECONDS.toSeconds(delayMillis));
        scheduleRefresh(delayMillis, TimeUnit.MILLISECONDS);
    }

    /**
     * Exponential backoff whose starting point and ceiling both depend on whether a
     * manifest is already cached - missing data is urgent, stale data is not.
     */
    private long retryDelayMillis() {
        boolean cached = cachedManifest != null;
        long initial = TimeUnit.SECONDS.toMillis(cached
                ? INITIAL_RETRY_WITH_MANIFEST_SECONDS
                : INITIAL_RETRY_WITHOUT_MANIFEST_SECONDS);
        long cap = TimeUnit.MINUTES.toMillis(cached
                ? MAX_RETRY_WITH_MANIFEST_MINUTES
                : MAX_RETRY_WITHOUT_MANIFEST_MINUTES);

        int doublings = Math.min(Math.max(consecutiveFailures - 1, 0), MAX_BACKOFF_DOUBLINGS);
        return jitter(Math.min(initial << doublings, cap));
    }

    /**
     * Spreads a delay by +/-{@link #JITTER_RATIO} so that an outage - which fails
     * every client at once - does not resolve into a synchronised burst of
     * retries when the API recovers.
     */
    private static long jitter(long delayMillis) {
        double factor = 1 + ((Math.random() * 2 - 1) * JITTER_RATIO);
        return Math.max(1, (long) (delayMillis * factor));
    }

    public @Nullable Manifest getManifest() {
        return cachedManifest;
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileConfig;
import com.runeprofile.RuneProfilePlugin;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
@Singleton
public class AutoSyncScheduler {
    @Inject
    private EventBus eventBus;

    @Inject
    private ScheduledExecutorService scheduledExecutorService;

    @Inject
    private RuneProfilePlugin plugin;

    @Inject
    private RuneProfileConfig config;

    // A reference to the pending auto-sync task
    private ScheduledFuture<?> autoSyncFuture;

    // Prevent multiple sync executions from overlapping
    private final AtomicBoolean isSyncing = new AtomicBoolean(false);

    // Store remaining time when paused on logout (in milliseconds)
    private static final TimeUnit PAUSE_TIME_UNIT = TimeUnit.SECONDS;
    private long remainingSyncPause = 0;

    private static final int RAPID_SYNC_SECONDS = 3;
    private static final int AUTO_SYNC_MINUTES = 60;

    public boolean isEnabled() {
        return config.autosyncProfile();
    }

    public void startUp() {
        log.debug("Auto sync scheduler starting up...");
        eventBus.register(this);
        if (isEnabled()) {
            resetAutoSyncTimer();
        }
    }

    public void shutDown() {
        log.debug("Auto sync scheduler shutting down...");
        eventBus.unregister(this);
        cancelScheduledSync();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals(RuneProfilePlugin.CONFIG_GROUP)) return;

        if (isEnabled()) {
            resetAutoSyncTimer();
        } else {
            cancelScheduledSync();
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (!isEnabled()) return;

        if (event.getGameState() != GameState.LOGGED_IN) {
            if (autoSyncFuture != null) {
                long remainingTime = autoSyncFuture.getDelay(PAUSE_TIME_UNIT);
                cancelScheduledSync();
                remainingSyncPause = remainingTime;
                log.debug("Player logged out, pausing sync timer. {} {} remaining.", remainingSyncPause, PAUSE_TIME_UNIT.toString().toLowerCase());
            }
        } else if (event.getGameState() == GameState.LOGGED_IN) {
            if (remainingSyncPause > 0) {
                log.debug("Resuming sync with {} {} remaining.", remainingSyncPause, PAUSE_TIME_UNIT.toString().toLowerCase());
                scheduleSyncWithDelay(remainingSyncPause, PAUSE_TIME_UNIT);
            } else {
                resetAutoSyncTimer();
            }
        }
    }

    /**
     * Called when a rapid sync is requested.
     * Cancels any existing scheduled sync and schedules a sync after 3 seconds.
     */
    public synchronized void startRapidSync(String eventSource) {
        log.debug("Starting rapid sync...");
        cancelScheduledSync();
        // Schedule a sync in 3 seconds, then resume normal cycle
        autoSyncFuture = scheduledExecutorService.schedule(() -> {
            performSync(eventSource);
            scheduleNextSync();
        }, RAPID_SYNC_SECONDS, TimeUnit.SECONDS);
    }

    /**
     * Resets the auto-sync cycle.
     */
    public synchronized void resetAutoSyncTimer() {
        if (!isEnabled()) {
            log.debug("Auto-sync is disabled; ignoring reset request.");
            return;
        }

        scheduleNextSync();
    }

    /**
     * Schedules the next sync after the configured auto-sync interval.
     */
    private synchronized void scheduleNextSync() {
        log.debug("Next sync scheduled in {} minutes", AUTO_SYNC_MINUTES);
        cancelScheduledSync();
        autoSyncFuture = scheduledExecutorService.schedule(() -> {
            performSync("auto-sync-interval");
            scheduleNextSync();
        }, AutoSyncScheduler.AUTO_SYNC_MINUTES, TimeUnit.MINUTES);
    }

    /**
     * Schedules a sync after a specific delay.
     * Any existing future or pause state is cancelled.
     *
     * @param delay The amount of time to wait before syncing, in nanoseconds.
     */
    private synchronized void scheduleSyncWithDelay(long delay, TimeUnit unit) {
        cancelScheduledSync();
        autoSyncFuture = scheduledExecutorService.schedule(() -> {
            performSync("auto-sync-resume");
            scheduleNextSync();
        }, delay, unit);
    }

    /**
     * Cancels any scheduled sync and clears the pause state.
     */
    private synchronized void cancelScheduledSync() {
        if (autoSyncFuture != null) {
            autoSyncFuture.cancel(false);
            autoSyncFuture = null;
        }
        remainingSyncPause = 0;
    }

    /**
     * Performs the actual sync, ensuring only one sync runs at a time.
     */
    private void performSync(String eventSource) {
        if (!isSyncing.compareAndSet(false, true)) {
            log.debug("Sync already in progress, skipping...");
            return;
        }

        log.debug("Syncing profile...");
        try {
            plugin.updateProfileAsync(true, eventSource);
        } finally {
            isSyncing.set(false);
        }
    }
}

package com.runeprofile.autosync;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Nameable;
import net.runelite.api.events.NameableNameChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import com.google.common.base.Strings;

import javax.inject.Inject;
import javax.inject.Singleton;

@Slf4j
@Singleton
public class RsnChangeSubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private AutoSyncScheduler autoSyncScheduler;

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    // Code from: WiseOldMan
    // Repository: https://github.com/wise-old-man/wiseoldman-runelite-plugin
    // License: BSD 2-Clause License
    private boolean isValidNameChange(String prev, String curr) {
        return !(Strings.isNullOrEmpty(prev)
                || curr.equals(prev)
                || prev.startsWith("[#")
                || curr.startsWith("[#"));
    }

    @Subscribe
    public void onNameableNameChanged(NameableNameChanged nameableNameChanged) {
        final Nameable nameable = nameableNameChanged.getNameable();

        if (!(nameable instanceof Player)) {
            return;
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null || nameable != localPlayer) {
            return;
        }

        String name = nameable.getName();
        String prev = nameable.getPrevName();

        if (!isValidNameChange(prev, name)) {
            log.debug("Ignoring invalid RSN change from '{}' to '{}'", prev, name);
            return;
        }

        log.debug("Detected RSN change from '{}' to '{}', scheduling rapid sync", prev, name);
        autoSyncScheduler.startRapidSync("rsn-change");
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileConfig;
import com.runeprofile.utils.PlayerState;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.Experience;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.EnumMap;
import java.util.Map;

@Slf4j
@Singleton
public class SkillSubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private AutoSyncScheduler autoSyncScheduler;

    private final Map<Skill, Integer> previousLevels = new EnumMap<>(Skill.class);
    private final Map<Skill, Integer> previousXp = new EnumMap<>(Skill.class);

    private boolean initialized = false;
    private int initTicksRemaining = 0;

    /**
     * Wait after login before initializing skill baselines.
     */
    private static final int INIT_GAME_TICKS = 16;

    private static final int[] XP_MILESTONES = {
            15_000_000, 20_000_000, 25_000_000, 30_000_000, 35_000_000, 40_000_000,
            45_000_000, 50_000_000, 55_000_000, 60_000_000, 65_000_000, 70_000_000,
            75_000_000, 80_000_000, 85_000_000, 90_000_000, 95_000_000, 100_000_000,
            105_000_000, 110_000_000, 115_000_000, 120_000_000, 125_000_000, 130_000_000,
            135_000_000, 140_000_000, 145_000_000, 150_000_000, 155_000_000, 160_000_000,
            165_000_000, 170_000_000, 175_000_000, 180_000_000, 185_000_000, 190_000_000,
            195_000_000, 200_000_000,
    };

    private static final int MAX_REAL_LEVEL = 99;

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
        reset();
    }

    private void reset() {
        previousLevels.clear();
        previousXp.clear();
        initialized = false;
        initTicksRemaining = 0;
    }

    private void initialize() {
        for (Skill skill : Skill.values()) {
            if (skill == Skill.OVERALL) continue;
            int xp = client.getSkillExperience(skill);
            int level = Experience.getLevelForXp(xp);
            previousXp.put(skill, xp);
            previousLevels.put(skill, level);
        }
        initialized = true;
        initTicksRemaining = 0;
        log.debug("SkillSubscriber initialized with current skill levels");
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            initTicksRemaining = INIT_GAME_TICKS;
        } else if (event.getGameState() != GameState.HOPPING) {
            reset();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (initTicksRemaining > 0) {
            initTicksRemaining--;
            if (initTicksRemaining == 0) {
                initialize();
            }
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (!initialized || !config.autosyncProfile() || !PlayerState.isValidPlayerState(client)) {
            return;
        }

        Skill skill = event.getSkill();
        if (skill == Skill.OVERALL) return;

        int newXp = event.getXp();
        int newLevel = Experience.getLevelForXp(newXp);

        Integer oldLevel = previousLevels.get(skill);
        Integer oldXp = previousXp.get(skill);

        if (oldLevel == null || oldXp == null) {
            previousLevels.put(skill, newLevel);
            previousXp.put(skill, newXp);
            return;
        }

        // Level up
        if (newLevel > oldLevel && newLevel <= MAX_REAL_LEVEL) {
            log.debug("Level up detected: {} {} -> {}", skill.getName(), oldLevel, newLevel);
            autoSyncScheduler.startRapidSync("level-up");
        }

        // XP milestones
        if (newLevel >= MAX_REAL_LEVEL && newXp > oldXp) {
            for (int milestone : XP_MILESTONES) {
                if (oldXp < milestone && newXp >= milestone) {
                    log.debug("XP milestone detected: {} crossed {}xp", skill.getName(), milestone);
                    autoSyncScheduler.startRapidSync("xp-milestone");
                    break;
                }
            }
        }

        previousLevels.put(skill, newLevel);
        previousXp.put(skill, newXp);
    }
}

package com.runeprofile.autosync;

import com.runeprofile.RuneProfileConfig;
import com.runeprofile.RuneProfilePlugin;
import com.runeprofile.data.Manifest;
import com.runeprofile.data.activities.ValuableDropActivity;
import com.runeprofile.utils.ItemUtils;
import com.runeprofile.utils.PlayerState;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;

@Slf4j
@Singleton
public class ValuableDropSubscriber {
    @Inject
    private EventBus eventBus;

    @Inject
    private ScheduledExecutorService scheduledExecutorService;

    @Inject
    private Client client;

    @Inject
    private ItemManager itemManager;

    @Inject
    private RuneProfilePlugin plugin;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private ManifestService manifestService;

    @SuppressWarnings("BooleanMethodIsAlwaysInverted")
    private boolean isEnabled() {
        return config.autosyncProfile() && config.trackValuableDrops() && PlayerState.isValidPlayerState(client);
    }

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onLootReceived(LootReceived event) {
        if (!isEnabled() || event.getType() == LootRecordType.PLAYER) {
            return;
        }

        handleItemsReceived(event.getItems());
    }

    private void handleItemsReceived(Collection<ItemStack> items) {
        List<ValuableDropActivity> valuableDrops = new ArrayList<>();

        Manifest manifest = manifestService.getManifest();
        Map<Integer, Integer> valueOverrides = buildValueOverrides(manifest);
        int threshold = resolveThreshold(manifest);

        for (ItemStack itemStack : items) {
            ItemComposition item = itemManager.getItemComposition(itemStack.getId());
            int itemId = ItemUtils.getUnnotedItemId(item);
            long value = ItemUtils.getPerceivedItemValue(itemManager, itemId, valueOverrides);

            if (value >= threshold) {
                for (int i = 0; i < itemStack.getQuantity(); i++) {
                    log.debug("Valuable drop detected: {} (ID: {}, Value: {})", item.getName(), itemId, value);
                    // Add each item as a separate drop
                    valuableDrops.add(new ValuableDropActivity(new ValuableDropActivity.Data(itemId, value)));
                }
            }
        }

        if (valuableDrops.isEmpty()) {
            return;
        }

        scheduledExecutorService.execute(() -> plugin.addActivitiesAsync(valuableDrops));
    }

    /**
     * Builds the item-id → value overrides from the manifest's special valuable
     * drops, or returns {@code null} when no manifest is loaded yet (values then
     * come straight from the GE price).
     */
    private @Nullable Map<Integer, Integer> buildValueOverrides(@Nullable Manifest manifest) {
        if (manifest == null) {
            return null;
        }

        Map<Integer, Integer> overrides = new HashMap<>();
        for (Manifest.SpecialValuableDrop drop : manifest.getSpecialValuableDrops()) {
            overrides.put(drop.getItemId(), drop.getValue());
        }
        return overrides;
    }

    private int resolveThreshold(@Nullable Manifest manifest) {
        if (manifest != null && manifest.getValuableDropThreshold() > 0) {
            return manifest.getValuableDropThreshold();
        }
        return ItemUtils.VALUABLE_DROP_THRESHOLD;
    }
}

