import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.components.LineComponent;

/**
 * OverlayPanel that suggests commands and possible aliases as the user types a command into the chat.
 */
@Slf4j
@Singleton
public class CommandSuggestionOverlay extends OverlayPanel {
    private static final int MAX_SUGGESTIONS = 5;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private RuneProfileConfig config;

    @Inject
    private ManifestService manifestService;

    @Inject
    public CommandSuggestionOverlay() {
        this.setLayer(OverlayLayer.ABOVE_SCENE);
        this.setResizable(false);
    }

    public void startUp() {
        this.overlayManager.add(this);
    }

    public void shutDown() {
        this.overlayManager.remove(this);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!this.config.commandSuggestionOverlay()) {
            return null;
        }

        if (this.client.isMenuOpen()) {
            return null;
        }

        String currentChatInput = this.client.getVarcStrValue(VarClientID.CHATINPUT);

        List<String> suggestions = this.getSuggestions(currentChatInput);
        if (suggestions.isEmpty()) {
            return null;
        }

        String searchTermForHighlight = this.getSearchTermForHighlight(currentChatInput);

        // Reading the panel gets awkward when the text for a suggestion wraps to a new line
        // So we update the panel width to fit the longest suggestion
        this.updatePanelWidth(graphics, suggestions);

        for (int i = suggestions.size() - 1; i >= 0; i--) { // Reverse order to have the nearest suggestions on the bottom
            this.addSuggestionToOverlay(suggestions.get(i), searchTermForHighlight);
        }

        return super.render(graphics);
    }

    // Returns a list of suggestions based on the current chat input
    private List<String> getSuggestions(String input) {
        if (input == null || input.trim().isEmpty()) {
            return new ArrayList<>();
        }

        if (!this.config.enableLogCommand()) {
            return new ArrayList<>(); // No suggestions if !log command is disabled
        }

        String lowerInput = input.toLowerCase().trim();
        String command = "!log";

        // Only show suggestions after "!log " is typed
        if (lowerInput.startsWith(command.toLowerCase() + " ")) {
            String remainder = input.substring(command.length()).trim();
            String lowerRemainder = remainder.toLowerCase();

            // "!log missing <page>" — suggest pages for the part after the keyword
            if (lowerRemainder.startsWith("missing ")) {
                return this.getPageSuggestions(remainder.substring("missing ".length()).trim());
            }

            List<String> suggestions = new ArrayList<>(this.getPageSuggestions(remainder));

            // Offer the "missing" keyword itself while the user is still typing it
            if (!remainder.isEmpty() && "missing".startsWith(lowerRemainder)) {
                suggestions.add(0, "missing");
                if (suggestions.size() > MAX_SUGGESTIONS) {
                    suggestions = suggestions.subList(0, MAX_SUGGESTIONS);
                }
            }

            return suggestions;
        }

        return new ArrayList<>();
    }

    // Get page name and alias suggestions from manifest
    private List<String> getPageSuggestions(String searchTerm) {
        String lowerSearch = searchTerm.toLowerCase();

        Manifest manifest = manifestService.getManifest();
        if (manifest == null || manifest.getPages() == null) {
            return new ArrayList<>();
        }

        List<String> matchingPages = new ArrayList<>();

        // Search through all page names and their aliases
        for (Map.Entry<String, List<String>> entry : manifest.getPages().entrySet()) {
            String pageName = entry.getKey();
            List<String> aliases = entry.getValue();

            // Check page name
            if (pageName.toLowerCase().contains(lowerSearch)) {
                matchingPages.add(pageName);
            }

            // Check aliases
            if (aliases != null) {
                for (String alias : aliases) {
                    if (alias.toLowerCase().contains(lowerSearch) && !matchingPages.contains(alias)) {
                        matchingPages.add(alias);
                    }
                }
            }
        }

        this.sortByRelevance(matchingPages, lowerSearch);

        int limit = Math.min(matchingPages.size(), MAX_SUGGESTIONS);
        return matchingPages.subList(0, limit);
    }

    private String getSearchTermForHighlight(String input) {
        if (input == null || input.trim().isEmpty()) {
            return "";
        }

        String lowerInput = input.toLowerCase().trim();
        String command = "!log";

        if (lowerInput.startsWith(command.toLowerCase() + " ")) {
            String remainder = input.substring(command.length()).trim();
            // Highlight the page-name portion, not the "missing" keyword
            if (remainder.toLowerCase().startsWith("missing ")) {
                return remainder.substring("missing ".length()).trim();
            }
            return remainder;
        }

        return input.trim();
    }

    private void updatePanelWidth(Graphics2D graphics, List<String> suggestions) {
        int maxWidth = 0;
        for (String suggestion : suggestions) {
            int width = graphics.getFontMetrics().stringWidth(suggestion);
            if (width > maxWidth) {
                maxWidth = width;
            }
        }
        int panelWidth = maxWidth + 20;
        this.setPreferredSize(new Dimension(panelWidth, 0));
    }

    private void addSuggestionToOverlay(String command, String searchTerm) {
        String highlightedText = this.createHighlightedText(command, searchTerm);
        LineComponent lineComponent = LineComponent.builder().left(highlightedText).build();

        this.panelComponent.getChildren().add(lineComponent);
    }

    private String createHighlightedText(String text, String searchTerm) {
        if (searchTerm.isEmpty()) {
            return text;
        }

        String lowerText = text.toLowerCase();
        String lowerSearch = searchTerm.toLowerCase();
        int index = lowerText.indexOf(lowerSearch);

        if (index == -1) {
            return text;
        }

        StringBuilder result = new StringBuilder();
        result.append(text.substring(0, index));
        result.append("<col=00ff00>");  // Green highlight
        result.append(text.substring(index, index + searchTerm.length()));
        result.append("<col=ffffff>");  // Reset to white
        result.append(text.substring(index + searchTerm.length()));

        return result.toString();
    }

    // Sorts with exact matches first, then prefix matches, then by position and length
    private void sortByRelevance(List<String> items, String searchTerm) {
        items.sort((a, b) -> {
            String termA = a.toLowerCase();
            String termB = b.toLowerCase();

            boolean exactA = termA.equals(searchTerm);
            boolean exactB = termB.equals(searchTerm);
            if (exactA != exactB) {
                return exactA ? -1 : 1;
            }

            boolean prefixA = termA.startsWith(searchTerm);
            boolean prefixB = termB.startsWith(searchTerm);
            if (prefixA != prefixB) {
                return prefixA ? -1 : 1;
            }

            int posA = termA.indexOf(searchTerm);
            int posB = termB.indexOf(searchTerm);
            if (posA != posB) {
                return Integer.compare(posA, posB);
            }

            return Integer.compare(termA.length(), termB.length());
        });
    }
}

package com.runeprofile.ui;

import com.runeprofile.RuneProfileApiClient;
import com.runeprofile.data.DefaultClogPageData;
import com.runeprofile.utils.AccountHash;
import com.runeprofile.utils.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.CompletableFuture;

@Slf4j
@Singleton
public class CollectionLogPageMenuOption {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private RuneProfileApiClient runeProfileApiClient;

    private static final List<Integer> collectionLogPageIds = Arrays.asList(40697867, 40697871, 40697888, 40697883, 40697890);

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    @SuppressWarnings("unused")
    public void onMenuEntryAdded(MenuEntryAdded event) {
        boolean isCollectionLogPageList = collectionLogPageIds.stream()
                .anyMatch(id -> id == event.getActionParam1());

        if (!isCollectionLogPageList) {
            return;
        }

        String target = event.getTarget();
        if (target.isEmpty()) {
            return;
        }

        String pageName = Utils.sanitize(target);

        client.getMenu().createMenuEntry(-2)
                .setTarget(target)
                .setOption("RuneProfile Default")
                .setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier())
                .onClick(e -> setDefaultPage(pageName));

    }

    private void setDefaultPage(String pageName) {
        CompletableFuture<DefaultClogPageData> dataFuture = new CompletableFuture<>();

        clientThread.invokeLater(() -> {
            dataFuture.complete(
                    new DefaultClogPageData(
                            AccountHash.getHashed(client),
                            pageName
                    )
            );
        });

        dataFuture.thenCompose(runeProfileApiClient::setDefaultClogPage).whenComplete((result, ex) -> {
            clientThread.invokeLater(() -> {
                String message = ex != null
                        ? Utils.getApiErrorMessage(ex, "Failed to set default collection log page.")
                        : "Default collection log page set to: " + pageName;

                client.addChatMessage(ChatMessageType.CONSOLE, "RuneProfile", message, "RuneProfile");
            });
        });
    }
}

package com.runeprofile.ui;

import com.google.common.collect.ImmutableList;
import com.runeprofile.RuneProfileConfig;
import com.runeprofile.utils.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

import javax.inject.Inject;

@Slf4j
public class ChatPlayerMenuOption {
    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private RuneProfileConfig config;

    // menu option
    private static final String KICK_OPTION = "Kick";
    private static final ImmutableList<String> AFTER_OPTIONS = ImmutableList.of("Message", "Add ignore", "Remove friend", "Delete", KICK_OPTION);

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event) {
        if (!config.showMenuLookupOption()) return;

        int groupId = WidgetUtil.componentToInterface(event.getActionParam1());
        String option = event.getOption();

        if (!AFTER_OPTIONS.contains(option)
                // prevent duplicate menu options in friends list
                || (option.equals("Delete") && groupId != InterfaceID.IGNORE)) {
            return;
        }

        boolean addMenuLookup = (groupId == InterfaceID.FRIENDS
                || groupId == InterfaceID.CHATCHANNEL_CURRENT
                || groupId == InterfaceID.CLANS_SIDEPANEL
                || groupId == InterfaceID.CLANS_GUEST_SIDEPANEL
                // prevent from adding for Kick option (interferes with the raiding party one)
                || groupId == InterfaceID.CHATBOX && !KICK_OPTION.equals(option)
                || groupId == InterfaceID.RAIDS_SIDEPANEL
                || groupId == InterfaceID.PM_CHAT
                || groupId == InterfaceID.IGNORE);

        if (addMenuLookup) {
            String username = Text.toJagexName(Text.removeTags(event.getTarget()));

            client.getMenu().createMenuEntry(-2)
                    .setTarget(event.getTarget())
                    .setOption("RuneProfile")
                    .setType(MenuAction.RUNELITE)
                    .setIdentifier(event.getIdentifier())
                    .onClick(e -> Utils.openProfileInBrowser(username));
        }
    }
}

package com.runeprofile.ui;

import com.google.gson.Gson;
import com.runeprofile.modelexporter.GlbExporter;
import com.runeprofile.utils.DevMode;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.CommandExecuted;
import net.runelite.client.RuneLite;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

import javax.inject.Inject;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Set;
import java.util.TreeSet;

/**
 * Development only {@code ::rpmodel} command that writes the local player's
 * model to {@code .runelite/runeprofile/models/}.
 */
@Slf4j
public class ModelDumpCommand {
    private static final String COMMAND = "rpmodel";
    private static final String DIRECTORY_NAME = "runeprofile";
    private static final String MODELS_DIRECTORY_NAME = "models";
    private static final DateTimeFormatter STAMP = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

    @Inject
    private EventBus eventBus;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private Gson gson;

    public void startUp() {
        if (DevMode.ENABLED) {
            eventBus.register(this);
        }
    }

    public void shutDown() {
        if (DevMode.ENABLED) {
            eventBus.unregister(this);
        }
    }

    @Subscribe
    public void onCommandExecuted(CommandExecuted event) {
        if (!COMMAND.equalsIgnoreCase(event.getCommand())) {
            return;
        }

        clientThread.invokeLater(this::dump);
    }

    private void dump() {
        final Player player = client.getLocalPlayer();
        if (player == null || player.getModel() == null) {
            report("No player model available yet.");
            return;
        }

        final String stamp = LocalDateTime.now().format(STAMP);
        write(player.getModel(), "player-" + stamp);

        final NPC pet = client.getFollower();
        final Model petModel = pet == null ? null : pet.getModel();
        if (petModel != null) {
            write(petModel, "pet-" + stamp);
        } else if (pet != null) {
            // Following but not yet rendered, so its model has not been built.
            report("Pet is out but has no model yet; move the camera onto it and retry.");
        } else {
            report("No pet out, so only the player was written.");
        }
    }

    /**
     * Reports the properties of a model that decide which paths the exporter
     * takes, so a dump says for itself whether it covered anything new.
     * <p>
     * Cheaper and more reliable than guessing at gear: most of what has gone
     * wrong so far was a case nothing happened to be wearing, and a line like
     * this would have said so immediately.
     */
    private void describe(Model model) {
        final StringBuilder notes = new StringBuilder();

        final Set<Integer> textures = new TreeSet<>();
        final short[] faceTextures = model.getFaceTextures();
        if (faceTextures != null) {
            for (int face = 0; face < model.getFaceCount(); face++) {
                if (faceTextures[face] != -1) {
                    textures.add((int) faceTextures[face]);
                }
            }
        }
        notes.append("textures=").append(textures.isEmpty() ? "none" : textures);

        // Whether any texture is cut out. The alpha=0 path has never been
        // exercised by a real model; every texture seen so far is fully opaque.
        boolean cutOut = false;
        for (int textureId : textures) {
            final int[] pixels = client.getTextureProvider().load(textureId);
            if (pixels == null) {
                continue;
            }
            for (int pixel : pixels) {
                if (pixel == 0) {
                    cutOut = true;
                    break;
                }
            }
        }
        notes.append(" cutOutTexture=").append(cutOut);

        int minAlpha = 255;
        final byte[] transparencies = model.getFaceTransparencies();
        if (transparencies != null) {
            for (int face = 0; face < model.getFaceCount(); face++) {
                minAlpha = Math.min(minAlpha, 255 - (transparencies[face] & 0xff));
            }
        }
        notes.append(" minAlpha=").append(minAlpha);

        // Model level transparency is not exported. It is 0 on everything seen
        // so far; anything else means a model would render more solid than the
        // game draws it.
        final int modelTransparency = model.getTransparency() & 0xff;
        if (modelTransparency != 0) {
            notes.append(" MODEL-TRANSPARENCY=").append(modelTransparency).append(" (not exported)");
        }

        // Above 65535 vertices the exporter switches to 32 bit indices, a path
        // no real model has reached.
        notes.append(" verts=").append(model.getVerticesCount());

        // Faces the exporter skips on purpose, and why.
        int hidden = 0;
        int invisible = 0;
        int nearlyInvisible = 0;
        final int[] colors3 = model.getFaceColors3();
        for (int face = 0; face < model.getFaceCount(); face++) {
            if (colors3[face] == -2) {
                hidden++;
            } else if (transparencies != null) {
                final int raw = transparencies[face] & 0xff;
                if (raw == 255) {
                    invisible++;
                } else if (raw == 254) {
                    nearlyInvisible++;
                }
            }
        }
        notes.append(" dropped(hidden=").append(hidden)
                .append(" invisible=").append(invisible)
                .append(" alpha254=").append(nearlyInvisible).append(")");

        report(notes.toString());
    }

    private void write(Model model, String name) {
        try {
            final byte[] glb = GlbExporter.toBytes(gson, client, model, name);
            final File file = writeFile(name + ".glb", glb);
            report(String.format("Wrote %s (%d faces, %d KB) to %s",
                    file.getName(), model.getFaceCount(), glb.length / 1024,
                    file.getParent()));
            describe(model);
        } catch (IOException | RuntimeException e) {
            log.warn("[rpmodel] export failed", e);
            report("Export failed: " + e.getMessage());
        }
    }

    /**
     * Reports into game chat as well as the log, since the usual way to run this
     * is a client started by double clicking a jar with no console in sight.
     */
    private void report(String message) {
        log.info("[rpmodel] {}", message);
        client.addChatMessage(ChatMessageType.CONSOLE, "RuneProfile", message, null);
    }

    private File writeFile(String fileName, byte[] contents) throws IOException {
        final File directory = new File(new File(RuneLite.RUNELITE_DIR, DIRECTORY_NAME),
                MODELS_DIRECTORY_NAME);
        if (!directory.exists() && !directory.mkdirs()) {
            throw new IOException("Could not create " + directory);
        }

        final File file = new File(directory, fileName);
        try (OutputStream out = new FileOutputStream(file)) {
            out.write(contents);
        }
        return file;
    }
}

package com.runeprofile.ui;

