package com.runeprofile;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.runeprofile.data.*;
import com.runeprofile.data.activities.ActivitiesResponse;
import com.runeprofile.data.activities.ActivityRecord;
import com.runeprofile.utils.RuneProfileApiException;
import lombok.NonNull;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLiteProperties;
import okhttp3.*;

import javax.annotation.Nullable;
import javax.inject.Inject;
import java.io.IOException;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.function.Consumer;

@Slf4j
public class RuneProfileApiClient {
    private static final MediaType JSON_MEDIA_TYPE = Objects.requireNonNull(MediaType.parse("application/json; charset=utf-8"));
    private static final MediaType MODEL_MEDIA_TYPE = Objects.requireNonNull(MediaType.parse("model/gltf-binary"));

    @Inject
    private OkHttpClient okHttpClient;

    private final String userAgent;

    // increment when making breaking changes to how the plugin users the API
    private static final String version = "2.0.0";

    private final HttpUrl baseUrl;

    @Inject
    private Gson gson;

    /**
     * Set with {@code -Druneprofile.localApi}, or {@code ./gradlew runClient
     * -PlocalApi}, to talk to a backend on localhost:8787.
     *
     * Deliberately not inferred from dev mode: a dev client is often the
     * only way to reproduce something against real data, and that should not
     * silently require a local backend.
     */
    private static final boolean LOCAL_API = Boolean.getBoolean("runeprofile.localApi");

    @Inject
    public RuneProfileApiClient() {
        String runeliteVersion = RuneLiteProperties.getVersion();
        userAgent = "RuneLite:" + runeliteVersion + "," + "Client:" + version;

        baseUrl = LOCAL_API
                ? new HttpUrl.Builder().scheme("http").host("localhost").port(8787).build()
                : new HttpUrl.Builder().scheme("https").host("api.runeprofile.com").build();
    }

    private HttpUrl buildApiUrl(String... pathSegments) {
        HttpUrl.Builder urlBuilder = baseUrl.newBuilder();
        for (String segment : pathSegments) {
            urlBuilder.addPathSegment(segment);
        }
        return urlBuilder.build();
    }

    private RequestBody createJsonBody(JsonObject jsonObject) {
        return RequestBody.create(JSON_MEDIA_TYPE, jsonObject.toString());
    }

    private Request.Builder buildApiRequest(HttpUrl url, Consumer<Request.Builder> methodSetter) {
        Request.Builder builder = new Request.Builder()
                .url(url)
                .header("Content-Type", "application/json")
                .header("User-Agent", userAgent);
        methodSetter.accept(builder);
        return builder;
    }

    private CompletableFuture<Response> executeHttpRequestAsync(OkHttpClient client, Request request) {
        CompletableFuture<Response> future = new CompletableFuture<>();
        client.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(@NonNull Call call, @NonNull IOException e) {
                log.error("Async API request failed.", e);
                future.completeExceptionally(e);
            }

            @Override
            public void onResponse(@NonNull Call call, @NonNull Response response) {
                future.complete(response);
            }
        });
        return future;
    }

    private CompletableFuture<Response> postHttpRequestAsync(HttpUrl url, String data) {
        RequestBody body = RequestBody.create(JSON_MEDIA_TYPE, data);
        Request request = buildApiRequest(url, builder -> builder.post(body)).build();
        log.debug("Sending json request to = {}, data = {}", url.toString(), data);
        return executeHttpRequestAsync(okHttpClient, request);
    }

    private CompletableFuture<Response> postHttpRequestAsync(HttpUrl url, MultipartBody data) {
        Request request = buildApiRequest(url, builder -> builder.post(data)).build();
        log.debug("Sending form data request to = {}, data = {}", url.toString(), data);
        return executeHttpRequestAsync(okHttpClient, request);
    }

    private CompletableFuture<Response> getHttpRequestAsync(HttpUrl url) {
        Request request = buildApiRequest(url, Request.Builder::get)
                .build();
        return executeHttpRequestAsync(okHttpClient, request);
    }

    private CompletableFuture<Response> deleteHttpRequestAsync(HttpUrl url) {
        Request request = buildApiRequest(url, Request.Builder::delete)
                .build();
        return executeHttpRequestAsync(okHttpClient, request);
    }

    private <T> T handleResponse(Response response, @Nullable Class<T> clazz) {
        try (Response res = response) {
            ResponseBody body = res.body();

            if (body == null) {
                throw new RuneProfileApiException("Response body is null");
            }

            String bodyString = body.string();

            if (!response.isSuccessful()) {
                String message = "Request failed (" + res.code() + ")";
                String code = null;
                try {
                    JsonObject json = gson.fromJson(bodyString, JsonObject.class);
                    if (json != null && json.has("message") && json.get("message").isJsonPrimitive()) {
                        message = json.get("message").getAsString();
                    }
                    if (json != null && json.has("code") && json.get("code").isJsonPrimitive()) {
                        code = json.get("code").getAsString();
                    }
                } catch (Exception e) {
                    log.debug("Failed to parse API error body: {}", bodyString, e);
                }
                throw new RuneProfileApiException(message, code, res.code());
            }

            if (clazz == null) {
                return null;
            }

            return gson.fromJson(bodyString, clazz);
        } catch (IOException e) {
            throw new RuneProfileApiException("Error reading response body");
        }
    }

    public CompletableFuture<UpdateProfileResult> updateProfileAsync(PlayerData data, String eventSource) {
        HttpUrl url = buildApiUrl("profiles");

        JsonObject payload = gson.toJsonTree(data).getAsJsonObject();
        payload.addProperty("eventSource", eventSource);

        return postHttpRequestAsync(url, gson.toJson(payload))
                .thenApply((response) -> handleResponse(response, UpdateProfileResult.class));
    }

    public CompletableFuture<ProfileSearchResult[]> searchProfiles(String query) {
        HttpUrl url = buildApiUrl("profiles").newBuilder()
                .addQueryParameter("q", query)
                .build();
        return getHttpRequestAsync(url)
                .thenApplyAsync((response) -> handleResponse(response, ProfileSearchResult[].class));
    }

    public CompletableFuture<AccountInfo> getAccountAsync(String accountHash) {
        HttpUrl url = buildApiUrl("profiles", "accounts", accountHash);
        return getHttpRequestAsync(url)
                .thenApplyAsync((response) -> handleResponse(response, AccountInfo.class));
    }

    public CompletableFuture<List<ActivityRecord>> getValuableDropsAsync(String accountHash, int limit) {
        HttpUrl url = buildApiUrl("profiles", "accounts", accountHash, "activities")
                .newBuilder()
                .addQueryParameter("activityTypes", "valuable_drop")
                .addQueryParameter("limit", String.valueOf(limit))
                .build();
        return getHttpRequestAsync(url)
                .thenApplyAsync((response) -> Objects.requireNonNull(handleResponse(response, ActivitiesResponse.class)).getActivities());
    }

    public CompletableFuture<Void> deleteActivityAsync(String accountHash, String activityId) {
        HttpUrl url = buildApiUrl("profiles", "accounts", accountHash, "activities", activityId);
        return deleteHttpRequestAsync(url)
                .thenApply((response) -> handleResponse(response, null));
    }

    public CompletableFuture<Void> deleteProfileAsync(String accountHash) {
        HttpUrl url = buildApiUrl("profiles", accountHash);
        return deleteHttpRequestAsync(url)
                .thenApply((response) -> handleResponse(response, null));
    }

    public CompletableFuture<Void> updateModelAsync(PlayerModelData data) {
        HttpUrl url = buildApiUrl("profiles", "models");

        RequestBody modelFile = RequestBody.create(MODEL_MEDIA_TYPE, data.getModel());

        MultipartBody.Builder bodyBuilder = new MultipartBody.Builder()
                .setType(MultipartBody.FORM)
                .addFormDataPart("accountId", data.getAccountHash())
                .addFormDataPart("model", "model.glb", modelFile);

        @Nullable
        byte[] petModel = data.getPetModel();
        if (petModel != null) {
            RequestBody petFile = RequestBody.create(MODEL_MEDIA_TYPE, petModel);
            bodyBuilder.addFormDataPart("petModel", "pet.glb", petFile);
        }

        MultipartBody body = bodyBuilder.build();

        return postHttpRequestAsync(url, body)
                .thenApplyAsync((response -> handleResponse(response, null)));
    }

    public CompletableFuture<CollectionLogPage> getCollectionLogPage(String username, String page) {
        HttpUrl url = buildApiUrl("profiles", username, "collection-log", page);
        return getHttpRequestAsync(url)
                .thenApplyAsync((response -> handleResponse(response, CollectionLogPage.class)));
    }

    public CompletableFuture<Void> setDefaultClogPage(DefaultClogPageData data) {
        HttpUrl url = buildApiUrl("profiles", "set-default-clog-page");
        return postHttpRequestAsync(url, gson.toJson(data))
                .thenApplyAsync((response) -> handleResponse(response, null));
    }

    public CompletableFuture<Void> addActivities(AddActivities data) {
        HttpUrl url = buildApiUrl("profiles", "activities");
        return postHttpRequestAsync(url, gson.toJson(data))
                .thenApplyAsync((response) -> handleResponse(response, null));
    }

    public CompletableFuture<Manifest> getManifest() {
        HttpUrl url = buildApiUrl("manifest");
        // Bypass RuneLite's persistent OkHttp disk cache
        Request request = buildApiRequest(url, Request.Builder::get)
                .cacheControl(CacheControl.FORCE_NETWORK)
                .build();
        return executeHttpRequestAsync(okHttpClient, request)
                .thenApplyAsync((response -> handleResponse(response, Manifest.class)));
    }
}

package com.runeprofile;

import com.google.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Singleton;

@Slf4j
@Singleton
public class ConfigMigration {
    private final ConfigManager configManager;

    @Inject
    private ConfigMigration(ConfigManager configManager) {
        this.configManager = configManager;
    }

    public void migrate() {
        migrateClogSyncButtonToMode();
    }

    /**
     * The "show_clog_sync_button" boolean was replaced by the "clog_sync_button_mode" enum.
     * true maps to the default (REPLACE_SEARCH), so only false needs an explicit write.
     */
    private void migrateClogSyncButtonToMode() {
        String oldValue = configManager.getConfiguration(RuneProfilePlugin.CONFIG_GROUP, "show_clog_sync_button");
        if (oldValue == null) {
            return;
        }

        if ("false".equals(oldValue)) {
            configManager.setConfiguration(RuneProfilePlugin.CONFIG_GROUP, "clog_sync_button_mode",
                    RuneProfileConfig.SyncButtonMode.DISABLED);
        }
        configManager.unsetConfiguration(RuneProfilePlugin.CONFIG_GROUP, "show_clog_sync_button");

        log.debug("Migrated show_clog_sync_button={} to clog_sync_button_mode", oldValue);
    }
}

