package com.runeprofile.panels;

import com.runeprofile.RuneProfileApiClient;
import com.runeprofile.autosync.PlayerDataService;
import com.runeprofile.data.activities.ActivityRecord;
import com.runeprofile.events.ProfileCreated;
import com.runeprofile.events.ProfileDeleted;
import com.runeprofile.utils.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.SwingUtil;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.plaf.basic.BasicButtonUI;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
public class DropsTabPanel extends JPanel {
    private static final int DROPS_LIMIT = 30;

    private final RuneProfileApiClient apiClient;
    private final PlayerDataService playerDataService;
    private final ItemManager itemManager;
    private final ClientThread clientThread;
    private final EventBus eventBus;

    private final JTextArea statusText = Utils.createParagraph("");
    private final JPanel listPanel = new JPanel();

    private final AtomicBoolean fetchInFlight = new AtomicBoolean(false);
    private volatile boolean stale = true;
    private volatile String accountId;

    private final List<ActivityRecord> records = new ArrayList<>();
    private final Map<Integer, String> itemNames = new HashMap<>();

    @Inject
    public DropsTabPanel(RuneProfileApiClient apiClient, PlayerDataService playerDataService, ItemManager itemManager, ClientThread clientThread, EventBus eventBus) {
        this.apiClient = apiClient;
        this.playerDataService = playerDataService;
        this.itemManager = itemManager;
        this.clientThread = clientThread;
        this.eventBus = eventBus;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(new EmptyBorder(10, 10, 10, 10));

        JTextArea description = Utils.createParagraph(
                "Recent valuable drops on your profile. "
                        + "Use this to remove duplicate or wrongly tracked drops. "
                        + "Deleting a drop is permanent and cannot be undone."
        );
        description.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(description);

        add(Box.createVerticalStrut(10));

        JPanel headerRow = new JPanel(new BorderLayout());
        headerRow.setOpaque(false);

        JLabel headerLabel = new JLabel("Recent Drops");
        headerLabel.setFont(FontManager.getRunescapeBoldFont());
        headerLabel.setForeground(Color.WHITE);
        headerRow.add(headerLabel, BorderLayout.WEST);

        JButton refreshButton = new JButton("Refresh");
        refreshButton.setFont(FontManager.getRunescapeSmallFont());
        refreshButton.addActionListener((e) -> refresh(true));
        headerRow.add(refreshButton, BorderLayout.EAST);

        headerRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        headerRow.setMaximumSize(new Dimension(Short.MAX_VALUE, headerRow.getPreferredSize().height));
        add(headerRow);

        add(Box.createVerticalStrut(8));

        statusText.setForeground(Color.GRAY);
        statusText.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(statusText);

        listPanel.setLayout(new BoxLayout(listPanel, BoxLayout.Y_AXIS));
        listPanel.setOpaque(false);
        listPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        add(listPanel);

        add(Box.createVerticalGlue());
    }

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onProfileCreated(ProfileCreated event) {
        markStale();
    }

    @Subscribe
    public void onProfileDeleted(ProfileDeleted event) {
        markStale();
    }

    public void markStale() {
        stale = true;
    }

    public void refresh(boolean force) {
        if (!force && !stale) return;
        fetchDrops();
    }

    private void fetchDrops() {
        if (!fetchInFlight.compareAndSet(false, true)) return;

        SwingUtilities.invokeLater(() -> {
            listPanel.removeAll();
            setStatus("Loading...", Color.GRAY);
            revalidate();
            repaint();
        });

        playerDataService.getAccountIdAsync().thenAccept((id) -> {
            if (id == null) {
                // not logged in yet - a refresh is triggered again on the next tab open
                fetchInFlight.set(false);
                log.debug("Account id not available yet, skipping drops fetch");
                SwingUtilities.invokeLater(() -> setStatus(null, Color.GRAY));
                return;
            }

            this.accountId = id;
            apiClient.getValuableDropsAsync(id, DROPS_LIMIT)
                .whenComplete((result, ex) -> {
                    fetchInFlight.set(false);

                    if (ex != null) {
                        log.warn("Failed to load valuable drops", ex);
                        SwingUtilities.invokeLater(() -> {
                            if (Utils.isAccountNotFound(ex)) {
                                setStatus("Create your profile first on the Profile tab.", Color.GRAY);
                            } else {
                                setStatus(Utils.getApiErrorMessage(ex, "Failed to load drops."), ColorScheme.PROGRESS_ERROR_COLOR);
                            }
                        });
                        return;
                    }

                    stale = false;
                    resolveItemNames(result);
                });
        });
    }

    /**
     * Item names are resolved on the client thread, then the list is rebuilt on the EDT.
     */
    private void resolveItemNames(List<ActivityRecord> fetchedRecords) {
        clientThread.invokeLater(() -> {
            Map<Integer, String> names = new HashMap<>();
            for (ActivityRecord record : fetchedRecords) {
                int itemId = record.getData().getItemId();
                if (!names.containsKey(itemId)) {
                    names.put(itemId, itemManager.getItemComposition(itemId).getName());
                }
            }

            SwingUtilities.invokeLater(() -> {
                records.clear();
                records.addAll(fetchedRecords);
                itemNames.clear();
                itemNames.putAll(names);
                rebuildList();
            });
        });
    }

    private void rebuildList() {
        listPanel.removeAll();

        if (records.isEmpty()) {
            setStatus("No valuable drops tracked yet.", Color.GRAY);
        } else {
            setStatus(null, Color.GRAY);
            for (ActivityRecord record : records) {
                listPanel.add(buildDropRow(record));
                listPanel.add(Box.createVerticalStrut(6));
            }
        }

        revalidate();
        repaint();
    }

    private JPanel buildDropRow(ActivityRecord record) {
        JPanel row = new JPanel(new BorderLayout());
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(4, 6, 4, 6));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);

        int itemId = record.getData().getItemId();

        JLabel iconLabel = new JLabel();
        iconLabel.setPreferredSize(new Dimension(36, 32));
        AsyncBufferedImage itemImage = itemManager.getImage(itemId);
        itemImage.addTo(iconLabel);
        row.add(iconLabel, BorderLayout.WEST);

        JPanel textPanel = new JPanel();
        textPanel.setLayout(new BoxLayout(textPanel, BoxLayout.Y_AXIS));
        textPanel.setOpaque(false);
        textPanel.setBorder(new EmptyBorder(0, 6, 0, 0));

        JLabel nameLabel = new JLabel(itemNames.getOrDefault(itemId, "Item " + itemId));
        nameLabel.setFont(FontManager.getRunescapeSmallFont());
        nameLabel.setForeground(Color.WHITE);
        textPanel.add(nameLabel);

        String value = Utils.formatQuantity(record.getData().getValue()) + " gp";
        JLabel detailsLabel = new JLabel(value + " · " + Utils.formatTimestamp(record.getCreatedAt()));
        detailsLabel.setFont(FontManager.getRunescapeSmallFont());
        detailsLabel.setForeground(Color.GRAY);
        textPanel.add(detailsLabel);

        row.add(textPanel, BorderLayout.CENTER);

        JButton deleteButton = buildDeleteButton(record);
        row.add(deleteButton, BorderLayout.EAST);

        row.setMaximumSize(new Dimension(Short.MAX_VALUE, Math.max(row.getPreferredSize().height, 40)));
        return row;
    }

    private static final ImageIcon DELETE_ICON = createXIcon(Color.GRAY);
    private static final ImageIcon DELETE_ICON_HOVER = createXIcon(ColorScheme.PROGRESS_ERROR_COLOR);

    private JButton buildDeleteButton(ActivityRecord record) {
        JButton deleteButton = new JButton(DELETE_ICON);
        SwingUtil.removeButtonDecorations(deleteButton);
        deleteButton.setUI(new BasicButtonUI());
        deleteButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        deleteButton.setPreferredSize(new Dimension(24, 24));
        deleteButton.setToolTipText("Delete this drop");
        deleteButton.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                deleteButton.setIcon(DELETE_ICON_HOVER);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                deleteButton.setIcon(DELETE_ICON);
            }
        });
        deleteButton.addActionListener((e) -> confirmAndDelete(record, deleteButton));
        return deleteButton;
    }

    /**
     * The RuneScape fonts have no glyph for an "✕" character, so the icon is drawn instead.
     */
    private static ImageIcon createXIcon(Color color) {
        int size = 16;
        int inset = 4;
        BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(color);
        g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g.drawLine(inset, inset, size - inset - 1, size - inset - 1);
        g.drawLine(size - inset - 1, inset, inset, size - inset - 1);
        g.dispose();
        return new ImageIcon(image);
    }

    private void confirmAndDelete(ActivityRecord record, JButton deleteButton) {
        int itemId = record.getData().getItemId();
        String itemName = itemNames.getOrDefault(itemId, "this drop");

        final int confirmed = JOptionPane.showConfirmDialog(
                this,
                "Delete " + itemName + " from your profile?\nThis cannot be undone.",
                "Confirm Drop Deletion",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
        );
        if (confirmed != JOptionPane.YES_OPTION) return;

        deleteButton.setEnabled(false);

        apiClient.deleteActivityAsync(accountId, record.getId())
                .whenComplete((result, ex) -> SwingUtilities.invokeLater(() -> {
                    if (ex != null) {
                        log.warn("Failed to delete activity", ex);
                        deleteButton.setEnabled(true);
                        JOptionPane.showMessageDialog(
                                this,
                                Utils.getApiErrorMessage(ex, "Failed to delete the drop."),
                                "RuneProfile",
                                JOptionPane.ERROR_MESSAGE
                        );
                        return;
                    }

                    records.removeIf((r) -> r.getId().equals(record.getId()));
                    rebuildList();
                }));
    }

    private void setStatus(String text, Color color) {
        statusText.setForeground(color);
        Utils.setParagraphText(statusText, text == null ? "" : text);
        statusText.setVisible(text != null);
    }
}

package com.runeprofile.panels;

import com.runeprofile.RuneProfileApiClient;
import com.runeprofile.RuneProfilePlugin;
import com.runeprofile.autosync.PlayerDataService;
import com.runeprofile.data.AccountInfo;
import com.runeprofile.events.ProfileCreated;
import com.runeprofile.events.ProfileDeleted;
import com.runeprofile.utils.Utils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
public class ProfileTabPanel extends JPanel {
    private static final String CARD_LOADING = "LOADING";
    private static final String CARD_INFO = "INFO";
    private static final String CARD_NO_PROFILE = "NO_PROFILE";
    private static final String CARD_ERROR = "ERROR";

    private final RuneProfilePlugin plugin;
    private final RuneProfileApiClient apiClient;
    private final PlayerDataService playerDataService;
    private final EventBus eventBus;

    private final CardLayout cardLayout = new CardLayout();

    private final JLabel usernameValue = createValueLabel();
    private final JLabel accountTypeValue = createValueLabel();
    private final JLabel clanValue = createValueLabel();
    private final JLabel createdValue = createValueLabel();
    private final JLabel updatedValue = createValueLabel();
    private JPanel clanRow;

    private final JTextArea errorText = Utils.createParagraph("");
    private JButton createProfileButton;

    private final AtomicBoolean fetchInFlight = new AtomicBoolean(false);
    private volatile boolean loadedOnce = false;

    @Inject
    public ProfileTabPanel(RuneProfilePlugin plugin, RuneProfileApiClient apiClient, PlayerDataService playerDataService, EventBus eventBus, MainButtonsPanel mainButtonsPanel) {
        this.plugin = plugin;
        this.apiClient = apiClient;
        this.playerDataService = playerDataService;
        this.eventBus = eventBus;

        setLayout(cardLayout);

        add(buildLoadingCard(), CARD_LOADING);
        add(buildInfoCard(mainButtonsPanel), CARD_INFO);
        add(buildNoProfileCard(), CARD_NO_PROFILE);
        add(buildErrorCard(), CARD_ERROR);

        cardLayout.show(this, CARD_LOADING);
    }

    public void startUp() {
        eventBus.register(this);
    }

    public void shutDown() {
        eventBus.unregister(this);
    }

    @Subscribe
    public void onProfileCreated(ProfileCreated event) {
        refresh(true);
    }

    @Subscribe
    public void onProfileDeleted(ProfileDeleted event) {
        refresh(true);
    }

    public void markStale() {
        loadedOnce = false;
    }

    public void refresh(boolean force) {
        if (!force && loadedOnce) return;
        if (!fetchInFlight.compareAndSet(false, true)) return;

        if (!loadedOnce) {
            SwingUtilities.invokeLater(() -> cardLayout.show(this, CARD_LOADING));
        }

        playerDataService.getAccountIdAsync().thenAccept((accountId) -> {
            if (accountId == null) {
                // not logged in yet - stay on the current card,
                // a refresh is triggered again when the login state is entered
                fetchInFlight.set(false);
                log.debug("Account id not available yet, skipping account info fetch");
                return;
            }

            apiClient.getAccountAsync(accountId)
                    .whenComplete((account, ex) -> {
                        fetchInFlight.set(false);

                        SwingUtilities.invokeLater(() -> {
                            if (ex == null) {
                                loadedOnce = true;
                                populateInfo(account);
                                cardLayout.show(this, CARD_INFO);
                                return;
                            }

                            if (Utils.isAccountNotFound(ex)) {
                                loadedOnce = true;
                                createProfileButton.setEnabled(true);
                                cardLayout.show(this, CARD_NO_PROFILE);
                                return;
                            }

                            log.warn("Failed to load account info", ex);
                            Utils.setParagraphText(errorText, Utils.getApiErrorMessage(ex, "Failed to load your account info."));
                            cardLayout.show(this, CARD_ERROR);
                        });
                    });
        });
    }

    private void populateInfo(AccountInfo account) {
        usernameValue.setText(account.getUsername());
        accountTypeValue.setText(account.getAccountType());

        boolean hasClan = account.getClanName() != null && !account.getClanName().isEmpty();
        clanValue.setText(hasClan ? account.getClanName() : "");
        clanRow.setVisible(hasClan);

        createdValue.setText(Utils.formatTimestamp(account.getCreatedAt()));
        updatedValue.setText(Utils.formatTimestamp(account.getUpdatedAt()));
    }

    private JPanel buildInfoCard(MainButtonsPanel mainButtonsPanel) {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBorder(new EmptyBorder(10, 10, 10, 10));

        JPanel infoContainer = new JPanel(new GridLayout(0, 1, 0, 6));
        infoContainer.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        infoContainer.setBorder(new EmptyBorder(8, 8, 8, 8));

        infoContainer.add(buildInfoRow("Username", usernameValue));
        infoContainer.add(buildInfoRow("Account Type", accountTypeValue));
        clanRow = buildInfoRow("Clan", clanValue);
        infoContainer.add(clanRow);
        infoContainer.add(buildInfoRow("Created", createdValue));
        infoContainer.add(buildInfoRow("Last Updated", updatedValue));

        infoContainer.setAlignmentX(Component.LEFT_ALIGNMENT);
        infoContainer.setMaximumSize(new Dimension(Short.MAX_VALUE, infoContainer.getPreferredSize().height));
        card.add(infoContainer);

        card.add(Box.createVerticalStrut(10));

        mainButtonsPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        mainButtonsPanel.setMaximumSize(new Dimension(Short.MAX_VALUE, mainButtonsPanel.getPreferredSize().height));
        card.add(mainButtonsPanel);

        card.add(Box.createVerticalGlue());
        return card;
    }

    private JPanel buildNoProfileCard() {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBorder(new EmptyBorder(10, 10, 10, 10));

        JTextArea guideText = Utils.createParagraph(
                "You don't have a RuneProfile yet.\n\n"
                        + "Create one to start tracking your progress. "
                        + "After creating it, open your collection log in-game to sync your collection log data, "
                        + "and update your player model from the Profile tab."
        );
        guideText.setAlignmentX(Component.LEFT_ALIGNMENT);
        card.add(guideText);

        card.add(Box.createVerticalStrut(10));

        createProfileButton = new JButton("Create Profile");
        createProfileButton.setPreferredSize(new Dimension(createProfileButton.getPreferredSize().width, 30));
        createProfileButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        createProfileButton.setMaximumSize(new Dimension(Short.MAX_VALUE, 30));
        createProfileButton.addActionListener((e) -> createProfile());
        card.add(createProfileButton);

        card.add(Box.createVerticalGlue());
        return card;
    }

    private void createProfile() {
        createProfileButton.setEnabled(false);
        try {
            plugin.updateProfileAsync(false, "manual-create")
                    .whenComplete((result, ex) -> SwingUtilities.invokeLater(() -> {
                        createProfileButton.setEnabled(true);
                        if (ex == null) {
                            // usually already triggered by the ProfileCreated event
                            refresh(true);
                        }
                    }));
        } catch (IllegalStateException ex) {
            log.warn("Could not create profile", ex);
            createProfileButton.setEnabled(true);
        }
    }

    private JPanel buildLoadingCard() {
        return buildMessageCard(createMessageLabel("Loading..."));
    }

    private JPanel buildErrorCard() {
        errorText.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
        errorText.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel card = buildMessageCard(errorText);

        JButton retryButton = new JButton("Retry");
        retryButton.setPreferredSize(new Dimension(retryButton.getPreferredSize().width, 30));
        retryButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        retryButton.setMaximumSize(new Dimension(Short.MAX_VALUE, 30));
        retryButton.addActionListener((e) -> refresh(true));
        card.add(Box.createVerticalStrut(10), 1);
        card.add(retryButton, 2);

        return card;
    }

    private JPanel buildMessageCard(JComponent content) {
        JPanel card = new JPanel();
        card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
        card.setBorder(new EmptyBorder(10, 10, 10, 10));
        card.add(content);
        card.add(Box.createVerticalGlue());
        return card;
    }

    private JPanel buildInfoRow(String labelText, JLabel valueLabel) {
        JPanel row = new JPanel(new BorderLayout());
        row.setOpaque(false);

        JLabel label = new JLabel(labelText);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(Color.GRAY);

        row.add(label, BorderLayout.WEST);
        row.add(valueLabel, BorderLayout.EAST);
        return row;
    }

    private static JLabel createValueLabel() {
        JLabel label = new JLabel();
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(Color.WHITE);
        return label;
    }

    private static JLabel createMessageLabel(String text) {
        JLabel label = new JLabel(text);
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(Color.GRAY);
        label.setAlignmentX(Component.LEFT_ALIGNMENT);
        return label;
    }

}

package com.runeprofile;

import com.runeprofile.panels.InvalidPanel;
import com.runeprofile.panels.LayoutPluginPanel;
import com.runeprofile.panels.HeaderPanel;
import com.runeprofile.utils.Icon;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;

@Slf4j
public class RuneProfilePanel extends PluginPanel {
    private final EventBus eventBus;
    private final Client client;
    private final ClientToolbar clientToolbar;
    private final RuneProfileConfig config;
    private final NavigationButton navigationButton;
    private final InvalidPanel invalidPanel;
    private final LayoutPluginPanel layoutPluginPanel;

    private boolean inSession = false;
    private volatile boolean panelActive = false;

    @Inject
    public RuneProfilePanel(EventBus eventBus, Client client, ClientToolbar clientToolbar, RuneProfileConfig config, HeaderPanel headerPanel, InvalidPanel invalidPanel, LayoutPluginPanel layoutPluginPanel) {
        super(false);
        setLayout(new BorderLayout());

        this.eventBus = eventBus;
        this.client = client;
        this.clientToolbar = clientToolbar;
        this.config = config;
        this.invalidPanel = invalidPanel;
        this.layoutPluginPanel = layoutPluginPanel;

        add(headerPanel, BorderLayout.NORTH);
        loadLoginState();

        final BufferedImage toolbarIcon = Icon.LOGO.getImage();
        navigationButton = NavigationButton.builder()
                .tooltip("RuneProfile")
                .icon(toolbarIcon)
                .panel(this)
                .priority(4)
                .build();
    }

    public void startUp() {
        eventBus.register(this);
        layoutPluginPanel.startUp();

        updateState(client.getGameState());

        if (config.showSidePanel()) {
            clientToolbar.addNavigation(navigationButton);
        }
    }

    public void shutDown() {
        eventBus.unregister(this);
        layoutPluginPanel.shutDown();

        clientToolbar.removeNavigation(navigationButton);
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if (!event.getGroup().equals(RuneProfilePlugin.CONFIG_GROUP)) return;

        if (config.showSidePanel()) {
            clientToolbar.addNavigation(navigationButton);
        } else {
            clientToolbar.removeNavigation(navigationButton);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        updateState(event.getGameState());
    }

    @Override
    public void onActivate() {
        panelActive = true;
        layoutPluginPanel.onPanelActivated();
    }

    @Override
    public void onDeactivate() {
        panelActive = false;
    }

    private void updateState(GameState state) {
        if (state == GameState.LOGGED_IN) {
            RuneScapeProfileType profileType = RuneScapeProfileType.getCurrent(client);
            if (profileType != RuneScapeProfileType.STANDARD) {
                inSession = false;
                loadInvalidPlayerState();
            } else {
                boolean sessionStarted = !inSession;
                inSession = true;
                loadValidState(sessionStarted);
            }
        } else if (state == GameState.LOGIN_SCREEN) {
            inSession = false;
            loadLoginState();
        }
    }

    private void loadValidState(boolean sessionStarted) {
        if (sessionStarted) {
            layoutPluginPanel.onSessionStarted(panelActive);
        }

        SwingUtilities.invokeLater(() -> {
            if (invalidPanel != null) {
                remove(invalidPanel);
            }

            add(layoutPluginPanel, BorderLayout.CENTER);
            revalidate();
            repaint();
        });
    }

    private void loadLoginState() {
        SwingUtilities.invokeLater(() -> {
            if (layoutPluginPanel != null) {
                remove(layoutPluginPanel);
            }

            invalidPanel.setHintText("Login to use this plugin.");
            add(invalidPanel, BorderLayout.CENTER);
            revalidate();
            repaint();
        });
    }

    private void loadInvalidPlayerState() {
        SwingUtilities.invokeLater(() -> {
            if (layoutPluginPanel != null) {
                remove(layoutPluginPanel);
            }

            invalidPanel.setHintText("Invalid world/mode.");
            add(invalidPanel, BorderLayout.CENTER);
            revalidate();
            repaint();
        });
    }
}

